// ============================================================
// MAGNATE MOTORS — Modo MULTI-CELULAR (estado compartido vía Firebase Firestore)
// ============================================================
(function () {
  "use strict";
  var D = window.MM_DATA;
  var L = window.MM_LOGIC;
  var $ = function (sel) { return document.querySelector(sel); };
  var root = null; // se asigna en boot()

  function ceil(x) { return Math.ceil(x); }
  function fmt(n) { return "$" + Math.round(n); }
  function esc(s) { return String(s).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]; }); }

  // Imagen del tablero aprobado (versión comprimida a JPEG para no inflar demasiado la página).
  var BOARD_IMG = "data:image/jpeg;base64,";

  // Posición (% del ancho/alto de la imagen del tablero) del centro de cada tarjeta de mercado,
  // estimada visualmente sobre la imagen final aprobada. Se usa para dibujar los puntos táctiles
  // sobre el mapa gráfico.
  var MARKET_COORDS = {
    eeuu:      { x: 11.4, y: 28.5 },
    alemania:  { x: 38.7, y: 29.5 },
    rusia:     { x: 52.1, y: 29.5 },
    japon:     { x: 74.9, y: 29.5 },
    corea:     { x: 89.8, y: 29.5 },
    mexico:    { x: 11.4, y: 44.2 },
    italia:    { x: 41.1, y: 44.2 },
    espana:    { x: 53.5, y: 44.2 },
    china:     { x: 74.9, y: 44.2 },
    brasil:    { x: 23.5, y: 57.1 },
    francia:   { x: 47.0, y: 57.1 },
    india:     { x: 87.4, y: 57.1 },
    sudafrica: { x: 41.1, y: 71.8 },
    australia: { x: 73.9, y: 71.8 }
  };

  // ================================================================
  // ESTADO — se lee del documento al cargar, se reconstruye al publicar
  // ================================================================
  var S = null;
  var mapOpen = false; // vista del tablero gráfico — estado local de esta pantalla, no se comparte
  var historyOpen = false; // vista de actividad reciente — estado local de esta pantalla, no se comparte
  var MY_ID_KEY_BASE = "mm_online_identity";
  var busy = false;       // evita doble-guardado mientras uno está en curso
  var FB_STATE = "checking"; // checking | ready | unavailable
  var dbRef = null;          // referencia de Firestore a la sala actual (games/<codigo>)
  var ROOM_CODE = null;      // código de sala, resuelto en boot()

  function myIdKey() { return MY_ID_KEY_BASE + "_" + (ROOM_CODE || "x"); }
  function getIdentity() { try { return localStorage.getItem(myIdKey()); } catch (e) { return null; } }
  function setIdentity(v) { try { if (v === null) localStorage.removeItem(myIdKey()); else localStorage.setItem(myIdKey(), v); } catch (e) {} }

  // ---- Sala (código de partida) ----
  // El estado del juego vive en Firestore, en games/<codigo>. Todos entran con el mismo
  // código (o el mismo link, que ya lo trae en la URL) y ven la partida en vivo — sin
  // "versiones" que fijar a mano ni recargas manuales.
  var ROOM_KEY = "mm_room_code";
  function roomFromUrl() {
    try {
      var m = /[?&]sala=([A-Za-z0-9]{3,10})/.exec(window.location.search);
      return m ? m[1].toUpperCase() : null;
    } catch (e) { return null; }
  }
  function getSavedRoom() { try { return localStorage.getItem(ROOM_KEY); } catch (e) { return null; } }
  function saveRoom(code) {
    try { localStorage.setItem(ROOM_KEY, code); } catch (e) {}
    try {
      var url = new URL(window.location.href);
      url.searchParams.set("sala", code);
      window.history.replaceState(null, "", url.toString());
    } catch (e) {}
  }
  function randomRoomCode() {
    var chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // sin 0/O ni 1/I, para que no se confundan al dictarlo
    var out = "";
    for (var i = 0; i < 4; i++) out += chars[Math.floor(Math.random() * chars.length)];
    return out;
  }
  function connectToRoom(code) {
    ROOM_CODE = code;
    dbRef = firebase.firestore().collection("games").doc(code);
    dbRef.onSnapshot(function (snap) {
      FB_STATE = "ready";
      var data = snap.data();
      S = migrateState(data && data.state !== undefined ? data.state : null);
      render();
    }, function (err) {
      FB_STATE = "unavailable";
      showError("No se pudo conectar con la sala (" + (err && err.code || "error") + "). Revisa tu conexión.");
      render();
    });
  }

  // ---- Borradores locales (localStorage) ----
  // Firestore redibuja la pantalla al instante cuando otro jugador guarda un cambio; si en
  // ese momento estabas escribiendo números en un formulario, el redibujado los borra. Para
  // que no se pierdan, cada input se guarda en localStorage mientras escribes y se restaura
  // al reconstruir la pantalla.
  function draftKeyFor(screen, myId) { return "mm_draft_" + (ROOM_CODE || "x") + "_" + screen + "_" + (S ? S.round + "_" + S.phase : "0_0") + "_" + myId; }
  function loadDraft(key) { try { var raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : null; } catch (e) { return null; } }
  function saveDraft(key, obj) { try { localStorage.setItem(key, JSON.stringify(obj)); } catch (e) {} }
  function clearDraft(key) { try { localStorage.removeItem(key); } catch (e) {} }

  function toast(msg, ms) {
    var t = document.createElement("div");
    t.className = "toast";
    t.textContent = msg;
    document.body.appendChild(t);
    setTimeout(function () { t.remove(); }, ms || 3200);
  }

  // showError(): banner de error VISIBLE en pantalla. No usamos window.showError()/confirm()
  // porque en algunos navegadores esas ventanas quedan bloqueadas y el clic parece "no hacer nada".
  function showError(msg) {
    var old = document.getElementById("mm-error-banner");
    if (old) old.remove();
    var b = document.createElement("div");
    b.id = "mm-error-banner";
    b.setAttribute("style", "position:fixed;left:10px;right:10px;bottom:16px;z-index:99;background:var(--bad-bg,#fbeaea);border:1px solid var(--bad,#c8433a);color:var(--bad,#c8433a);padding:12px 14px;border-radius:10px;font-size:.88rem;box-shadow:0 8px 24px -12px rgba(0,0,0,.4);");
    b.textContent = "⚠ " + msg;
    var closeBtn = document.createElement("span");
    closeBtn.textContent = " ✕";
    closeBtn.style.cssText = "float:right;cursor:pointer;font-weight:700;";
    closeBtn.onclick = function () { b.remove(); };
    b.appendChild(closeBtn);
    document.body.appendChild(b);
    setTimeout(function () { if (b.parentNode) b.remove(); }, 9000);
  }
  window.addEventListener("error", function (e) {
    showError("Error inesperado: " + (e && e.message ? e.message : "algo falló") + ". Si se repite, recarga la página.");
  });

  // commit(): guarda el estado mutado en S como el nuevo documento compartido de la sala.
  // Firestore avisa EN VIVO a todos los que tengan la página abierta — nadie tiene que
  // recargar la página ni "elegir la versión más reciente" a mano.
  function commit() {
    if (busy) return;
    if (!dbRef) { toast("No se puede guardar: no hay conexión con la sala todavía."); return; }
    busy = true;
    dbRef.set({ state: S === undefined ? null : S, updatedAt: Date.now() }).then(function () {
      busy = false;
      // El onSnapshot de esta misma pestaña también recibe este cambio y vuelve a dibujar,
      // así que no hace falta llamar a render() aquí.
    }).catch(function (err) {
      busy = false;
      var code = err && err.code;
      if (code === "permission-denied") {
        toast("No tienes permiso para guardar en esta sala. Revisa las reglas de Firestore.");
      } else if (code === "unavailable") {
        toast("Sin conexión — reintenta en un momento.");
      } else {
        toast("No se pudo guardar (" + (code || "error") + "). Intenta de nuevo.");
      }
      render();
    });
  }

  // ================================================================
  // Utilidades de juego (idénticas en espíritu a la versión de un solo celular)
  // ================================================================
  function log(msg) { S.log = S.log || []; S.log.unshift("R" + S.round + "F" + S.phase + ": " + msg); if (S.log.length > 40) S.log.length = 40; }
  function playerById(id) { return S.players.filter(function (p) { return p.id === id; })[0]; }

  function computeTurnOrder() {
    var arr = S.players.slice();
    arr.sort(function (a, b) {
      if (a.stockValue !== b.stockValue) return a.stockValue - b.stockValue;
      return a.stockValueInicial - b.stockValueInicial;
    });
    S.turnOrder = arr.map(function (p) { return p.id; });
    S.turnIndex = 0;
  }

  function activeEventFlags() {
    var flags = {};
    (S.events.active || []).forEach(function (e) {
      if (e.tipo === "costoProduccion") flags.lineaMontaje = true;
      if (e.tipo === "costoProduccionContinente" && e.continente === "Asia") flags.toyotaAsia = true;
      if (e.tipo === "trasladoContinente") flags.autopistasModernas = true;
      if (e.tipo === "traslado0") flags.tlcan = true;
      if (e.tipo === "bonoMotorAlto") flags.augeVE = true;
      if (e.tipo === "topeProduccion") flags.topeProduccionEvento = e.valor;
      if (e.id === "segunda_guerra") flags.costoProduccionExtra = 1;
    });
    return flags;
  }

  function marketDemand(marketId) {
    var m = D.MARKETS[marketId];
    var base = m.demanda;
    (S.events.active || []).forEach(function (e) {
      if (e.tipo === "demandaGlobal") base += e.valor;
      if (e.tipo === "demandaContinente" && e.continente === m.continente) base += e.valor;
      if (e.tipo === "demandaPrecioMax" && m.precioMax <= e.maxPrecio) base += e.valor;
      if (e.tipo === "demandaMercado" && e.mercado === marketId) base += e.valor;
      if (e.id === "segunda_guerra" && m.continente === "Europa") base -= 2;
      if (e.id === "crisis_petroleo") base -= 2;
    });
    return Math.max(base, 0);
  }
  function regulatoryRequirement() {
    var req = 0;
    (S.events.active || []).forEach(function (e) { if (e.tipo === "regulatorio") req = Math.max(req, e.valor); });
    return req;
  }

  function currentTurnPlayer() { return playerById(S.turnOrder[S.turnIndex]); }

  function transportTotalForAlloc(p, alloc) {
    var total = 0;
    var flags = activeEventFlags();
    var remaining = {};
    Object.keys(p.inventory).forEach(function (mid) { remaining[mid] = p.inventory[mid]; });
    Object.keys(alloc).forEach(function (destMid) {
      var need = alloc[destMid].unidades;
      var sources = Object.keys(remaining).sort(function (a, b) {
        return L.transportCost(p, a, destMid, flags) - L.transportCost(p, b, destMid, flags);
      });
      sources.forEach(function (srcMid) {
        if (need <= 0) return;
        var take = Math.min(need, remaining[srcMid] || 0);
        if (take <= 0) return;
        total += take * L.transportCost(p, srcMid, destMid, flags);
        remaining[srcMid] -= take;
        need -= take;
      });
    });
    return total;
  }

  // ---------------- Decisiones CPU ----------------
  function botProduce(p) {
    var flags = activeEventFlags();
    var capPer = L.productionCapPerFactory(p, flags);
    // No produce a ciegas: estima cuánto puede vender realmente (según sus mercados) y no
    // fabrica mucho más que eso, para no quedarse con inventario varado.
    var ventaEstimada = p.offices.reduce(function (s, mid) {
      var tieneFabrica = p.factories.indexOf(mid) !== -1;
      return s + L.marketCap(p, mid, tieneFabrica);
    }, 0) + L.extraUnits(p, flags);
    var inventarioActual = Object.keys(p.inventory).reduce(function (s, k) { return s + p.inventory[k]; }, 0);
    var objetivo = Math.max(0, ventaEstimada - inventarioActual);
    var budget = Math.floor(p.cash * 0.65);
    // Produce primero donde le sale más barato (mejor margen).
    var factories = p.factories.slice().sort(function (a, b) { return L.productionCost(p, a, flags) - L.productionCost(p, b, flags); });
    var produced = {}, total = 0, restante = objetivo;
    factories.forEach(function (mid) {
      var cost = L.productionCost(p, mid, flags);
      var maxAsequible = Math.floor(budget / cost);
      var units = Math.max(0, Math.min(capPer, maxAsequible, restante));
      produced[mid] = units; budget -= units * cost; total += units * cost; restante -= units;
    });
    p.cash -= total;
    Object.keys(produced).forEach(function (mid) { p.inventory[mid] = (p.inventory[mid] || 0) + produced[mid]; });
    log(p.name + " (CPU) produjo por " + fmt(total));
  }

  function botBuyPatents(p) {
    var bought = 0;
    while (bought < 2) {
      var offers = [];
      S.players.forEach(function (owner) {
        if (owner.id === p.id) return;
        Object.keys(D.PATENTES).forEach(function (branch) {
          var devLevels = owner.patenteDevLevels ? owner.patenteDevLevels[branch] || [] : [];
          devLevels.forEach(function (entry) {
            var nivel = entry.nivel, myLevel = p.patentes[branch] || 0;
            if (myLevel >= nivel || nivel - myLevel !== 1) return;
            offers.push({ branch: branch, nivel: nivel, ownerId: owner.id, precio: D.PATENTES[branch].niveles[nivel].compra });
          });
        });
      });
      var freeAvailable = D.COMPANIES[p.companyId].id === "kogane" && !p.koganeUsedThisRound;
      var cheap = offers.filter(function (o) { return freeAvailable || o.precio <= Math.max(6, p.cash * 0.12); });
      cheap.sort(function (a, b) { return a.precio - b.precio; });
      if (!cheap.length) break;
      var o = cheap[0], price = freeAvailable ? 0 : o.precio;
      if (price > p.cash) break;
      var owner = playerById(o.ownerId);
      p.cash -= price; owner.cash += price; p.patentes[o.branch] = o.nivel;
      if (price === 0) p.koganeUsedThisRound = true;
      log(p.name + " (CPU) compró " + D.PATENTES[o.branch].nombre + " Nv" + o.nivel + " por $" + price);
      bought++;
    }
  }

  function botDevelop(p) {
    var maxDev = L.hasKnow(p, "plataforma_modular") ? 2 : 1;
    for (var i = 0; i < maxDev; i++) {
      var patentOptions = [];
      Object.keys(D.PATENTES).forEach(function (branch) {
        var myLevel = p.patentes[branch] || 0, nextLevel = myLevel + 1;
        if (nextLevel > 5) return;
        var already = S.players.some(function (pl) { return pl.patenteDevLevels && pl.patenteDevLevels[branch] && pl.patenteDevLevels[branch].some(function (e) { return e.nivel === nextLevel; }); });
        if (already) return;
        patentOptions.push({ branch: branch, nivel: nextLevel, costo: L.developmentCost(p, D.PATENTES[branch].niveles[nextLevel].desarrollo) });
      });
      var knowOptions = D.KNOWHOW.filter(function (k) { return k.ronda <= S.round && !S.players.some(function (pl) { return pl.knowhow.indexOf(k.id) !== -1; }); })
        .map(function (k) { return { id: k.id, nombre: k.nombre, costo: k.precio }; });
      var all = patentOptions.map(function (o) { return { type: "patent", o: o, costo: o.costo }; })
        .concat(knowOptions.map(function (o) { return { type: "know", o: o, costo: o.costo }; }))
        .filter(function (x) { return x.costo <= p.cash; });
      if (!all.length) break;
      all.sort(function (a, b) { return a.costo - b.costo; });
      var pick = all[0];
      if (pick.type === "patent") {
        var o2 = pick.o;
        p.cash -= o2.costo; p.patentes[o2.branch] = o2.nivel;
        p.patenteDevLevels = p.patenteDevLevels || {}; p.patenteDevLevels[o2.branch] = p.patenteDevLevels[o2.branch] || [];
        p.patenteDevLevels[o2.branch].push({ nivel: o2.nivel });
        p.patentesDesarrolladas[o2.branch] = Math.max(p.patentesDesarrolladas[o2.branch] || 0, o2.nivel);
        log(p.name + " (CPU) desarrolló " + D.PATENTES[o2.branch].nombre + " Nv" + o2.nivel);
      } else {
        p.cash -= pick.o.costo; p.knowhow.push(pick.o.id);
        log(p.name + " (CPU) tomó Know-How " + pick.o.nombre);
      }
    }
  }

  function botExpand(p) {
    var flags = activeEventFlags();
    var homeContinent = D.MARKETS[p.factories[0]] ? D.MARKETS[p.factories[0]].continente : null;
    var maxFab = L.maxFactories(p);
    var budget = Math.floor(p.cash * 0.6);

    // 1) Si le conviene, construye una fábrica en un mercado donde ya tiene oficina y el margen
    //    de venta es bueno, para dejar de depender de importar/comprar producción cara.
    if (p.factories.length < maxFab) {
      var factoryCandidates = p.offices.filter(function (mid) { return p.factories.indexOf(mid) === -1; }).map(function (mid) {
        var m = D.MARKETS[mid], foreign = homeContinent && m.continente !== homeContinent;
        var barrera = L.expansionBarrier(p, mid, foreign, flags);
        var cost = barrera + L.expansionBuildCost(p, "fabrica");
        var margen = m.precioMax - 3; // aproximación de margen de venta vs costo típico de producción
        return { mid: mid, m: m, cost: cost, margen: margen };
      }).filter(function (c) { return c.cost <= budget && c.margen > 2; });
      factoryCandidates.sort(function (a, b) { return b.margen - a.margen; });
      if (factoryCandidates.length) {
        var fc = factoryCandidates[0];
        p.cash -= fc.cost; budget -= fc.cost; p.factories.push(fc.mid);
        log(p.name + " (CPU) construyó fábrica en " + fc.m.name);
      }
    }

    // 2) Abre oficinas nuevas priorizando mercados propios (más baratos) y con mejor precio de venta.
    var expansions = 0;
    while (expansions < 2) {
      var candidates = Object.keys(D.MARKETS).filter(function (mid) { return p.offices.indexOf(mid) === -1; }).map(function (mid) {
        var m = D.MARKETS[mid], foreign = homeContinent && m.continente !== homeContinent;
        var barrera = L.expansionBarrier(p, mid, foreign, flags);
        return { mid: mid, m: m, cost: barrera + L.expansionBuildCost(p, "oficina"), foreign: foreign, margen: m.precioMax };
      }).filter(function (c) { return c.cost <= budget; });
      candidates.sort(function (a, b) {
        if (a.foreign !== b.foreign) return a.foreign ? 1 : -1;
        if (b.margen !== a.margen) return b.margen - a.margen;
        return a.cost - b.cost;
      });
      if (!candidates.length) break;
      var c = candidates[0];
      p.cash -= c.cost; budget -= c.cost; p.offices.push(c.mid);
      log(p.name + " (CPU) abrió oficina en " + c.m.name);
      expansions++;
    }
  }

  function botDistribute(p) {
    var flags = activeEventFlags();
    var totalInv = Object.keys(p.inventory).reduce(function (s, k) { return s + p.inventory[k]; }, 0);
    if (totalInv <= 0) { S.distributionData[p.id] = { alloc: {}, extraMarket: "", unassigned: 0 }; return; }
    var extra = L.extraUnits(p, flags);
    var candidates = p.offices.map(function (mid) {
      var m = D.MARKETS[mid], tieneFabrica = p.factories.indexOf(mid) !== -1;
      var cap = L.marketCap(p, mid, tieneFabrica);
      var costRef = tieneFabrica ? L.productionCost(p, mid, flags) : 3;
      return { mid: mid, m: m, cap: cap, margin: m.precioMax - costRef };
    }).sort(function (a, b) { return b.margin - a.margin; });
    var alloc = {}, remaining = totalInv;
    candidates.forEach(function (c) {
      if (remaining <= 0) return;
      var take = Math.min(remaining, c.cap);
      if (take <= 0) return;
      alloc[c.mid] = { unidades: take, precio: Math.max(1, c.m.precioMax - 1) };
      remaining -= take;
    });
    var guard = 0;
    while (transportTotalForAlloc(p, alloc) > p.cash && guard < 200) {
      var keys = Object.keys(alloc).filter(function (k) { return alloc[k].unidades > 0; });
      if (!keys.length) break;
      alloc[keys[0]].unidades -= 1;
      if (alloc[keys[0]].unidades <= 0) delete alloc[keys[0]];
      guard++;
    }
    var transporte = transportTotalForAlloc(p, alloc);
    p.cash -= Math.max(0, transporte);
    var extraMarket = "", bestQty = -1;
    Object.keys(alloc).forEach(function (mid) { if (alloc[mid].unidades > bestQty) { bestQty = alloc[mid].unidades; extraMarket = mid; } });
    S.distributionData[p.id] = { alloc: alloc, extraMarket: extraMarket, unassigned: Math.max(0, remaining) };
    log(p.name + " (CPU) distribuyó su inventario y pagó $" + Math.round(transporte) + " de traslado");
  }

  // ================================================================
  // RENDER
  // ================================================================
  function header(faseNombre) {
    var myId = getIdentity();
    return '<div class="hdr">' +
      '<div class="hdr-top"><span class="badge">Ronda ' + S.round + '/5</span><span class="badge">Fase ' + S.phase + '/9 — ' + faseNombre + '</span>' +
      '<button class="btn small" id="mapBtn">' + (mapOpen ? '◀ Volver al juego' : '🗺️ Ver tablero') + '</button>' +
      '<button class="btn small" id="historyBtn">' + (historyOpen ? '◀ Volver al juego' : '📜 Actividad') + '</button>' +
      '<button class="btn small" id="whoBtn">Soy: ' + (myId ? esc(playerLabel(myId)) : "?") + '</button></div>' +
      '<div class="hdr-players">' + S.players.map(function (p) {
        var c = D.COMPANIES[p.companyId];
        return '<div class="mini-player' + (p.id === myId ? ' me' : '') + '"><b>' + esc(p.name) + '</b><span>' + c.name + '</span><span>' + fmt(p.cash) + ' · acc $' + p.stockValue + '</span></div>';
      }).join("") + '</div></div>';
  }
  function playerLabel(id) {
    if (id === "spectator") return "Espectador";
    var p = playerById(id);
    return p ? p.name : "?";
  }
  function wireWhoBtn() {
    var b = $("#whoBtn");
    if (b) b.onclick = function () { setIdentity(null); render(); };
    var mb = $("#mapBtn");
    if (mb) mb.onclick = function () { mapOpen = !mapOpen; if (mapOpen) historyOpen = false; render(); };
    var hb = $("#historyBtn");
    if (hb) hb.onclick = function () { historyOpen = !historyOpen; if (historyOpen) mapOpen = false; render(); };
  }

  // ---------------- ACTIVIDAD RECIENTE (historial completo, no solo de la fase actual) ----------------
  // Como el juego avanza por turnos y fases, lo que hicieron otros jugadores DESPUÉS de tu
  // turno queda registrado pero puede quedar fuera de la vista filtrada por fase (turnHistoryHtml).
  // Esta pantalla siempre muestra los últimos movimientos de toda la partida, sin filtrar por fase.
  function renderHistory() {
    var entries = (S.log || []).slice(0, 40);
    root.innerHTML = header("Actividad") + '<div class="screen"><h2>Actividad reciente</h2>' +
      '<p class="muted">Todo lo que ha pasado en la partida, más reciente primero.</p>' +
      '<div class="card" style="text-align:left;">' +
      (entries.length ? entries.map(function (e) { return '<div class="salerow">' + esc(e) + '</div>'; }).join("") : '<p class="muted">Todavía no hay actividad.</p>') +
      '</div></div>';
    wireWhoBtn();
  }

  // ---------------- TABLERO GRÁFICO (mapa real del juego, con puntos por mercado) ----------------
  function marketPresenceSummary(mid) {
    var lines = [];
    S.players.forEach(function (p) {
      var hasOffice = p.offices.indexOf(mid) !== -1;
      var hasFactory = p.factories.indexOf(mid) !== -1;
      var inv = p.inventory[mid] || 0;
      if (hasOffice || hasFactory || inv > 0) {
        lines.push({ id: p.id, name: p.name, company: D.COMPANIES[p.companyId].name, hasOffice: hasOffice, hasFactory: hasFactory, inv: inv });
      }
    });
    return lines;
  }
  function renderBoardMap() {
    var myId = getIdentity();
    var me = (myId && myId !== "spectator") ? playerById(myId) : null;
    root.innerHTML = header("Tablero") + '<div class="screen"><h2>Tablero Principal</h2>' +
      '<div style="position:relative;width:100%;border-radius:10px;overflow:hidden;box-shadow:var(--shadow);line-height:0;">' +
      '<img src="' + BOARD_IMG + '" style="display:block;width:100%;height:auto;" alt="Tablero Magnate Motors">' +
      Object.keys(MARKET_COORDS).map(function (mid) {
        var c = MARKET_COORDS[mid];
        var mine = me && (me.offices.indexOf(mid) !== -1 || me.factories.indexOf(mid) !== -1 || (me.inventory[mid] || 0) > 0);
        var anyone = S.players.some(function (p) { return p.offices.indexOf(mid) !== -1 || p.factories.indexOf(mid) !== -1; });
        var color = mine ? "#1f8a5c" : (anyone ? "#a9781f" : "rgba(120,120,120,.6)");
        return '<button class="map-dot" data-m="' + mid + '" style="position:absolute;left:' + c.x + '%;top:' + c.y + '%;transform:translate(-50%,-50%);width:24px;height:24px;border-radius:50%;background:' + color + ';border:2px solid #fff;box-shadow:0 1px 5px rgba(0,0,0,.5);cursor:pointer;padding:0;"></button>';
      }).join("") +
      '</div>' +
      '<p class="muted" style="margin-top:8px;">Toca un punto para ver quién tiene presencia ahí. <span style="color:#1f8a5c;">●</span> tú · <span style="color:#a9781f;">●</span> otro jugador · <span style="color:rgba(120,120,120,.8);">●</span> nadie todavía.</p>' +
      '<div id="mapDetail"></div>' +
      '</div>';
    wireWhoBtn();
    root.querySelectorAll(".map-dot").forEach(function (btn) {
      btn.onclick = function () {
        var mid = btn.dataset.m, m = D.MARKETS[mid];
        var lines = marketPresenceSummary(mid);
        $("#mapDetail").innerHTML = '<div class="card"><h3>' + m.name + '</h3>' +
          '<p class="muted">P.Máx $' + m.precioMax + ' · Costo $' + m.costo + ' · Barrera $' + m.barrera + ' · Demanda ' + m.demanda + ' · Tope ' + m.tope + '</p>' +
          (lines.length ? lines.map(function (l) {
            return '<div class="salerow"><b>' + esc(l.name) + '</b> (' + esc(l.company) + ')' +
              (l.hasFactory ? ' · fábrica' : (l.hasOffice ? ' · oficina' : "")) +
              (l.inv > 0 ? ' · ' + l.inv + ' unid. en bodega ahí' : "") + '</div>';
          }).join("") : '<p class="muted">Nadie tiene presencia todavía.</p>') +
          '</div>';
      };
    });
  }

  function render() {
    root = $("#app");
    if (FB_STATE === "unavailable") { renderNoHost(); return; }
    if (!ROOM_CODE) { renderRoomGate(); return; }
    if (FB_STATE === "checking") { renderChecking(); return; }
    if (!S) { renderSetup(); return; }
    var myId = getIdentity();
    if (myId === null) { renderIdentityPicker(); return; }
    if (S.finished) { renderFinal(); return; }
    if (mapOpen) { renderBoardMap(); return; }
    if (historyOpen) { renderHistory(); return; }
    if (S.pendingMonopoly && S.pendingMonopoly.length && S.pendingMonopoly.some(function (c) { return !c.resolved; })) { renderMonopolyResolution(); return; }
    switch (S.phase) {
      case 1: renderProduction(); break;
      case 2: renderPatentPurchase(); break;
      case 3: renderDevelopment(); break;
      case 4: renderExpansion(); break;
      case 5: renderDistribution(); break;
      case 6: renderSaleResolution(); break;
      case 7: if (!dividendVotesComplete()) { renderDividendVote(); } else { renderAdjustment(); } break;
      case 8: renderStockMarket(); break;
      case 9: renderEvents(); break;
      default: renderProduction();
    }
  }

  // ---------------- SALA (código de partida) ----------------
  // Antes de tocar Firestore, cada quien elige: crear una sala nueva (le da un código de 4
  // letras a compartir) o unirse con el código que le pasaron. Una vez elegido, queda guardado
  // en este celular y en la URL, así que basta con abrir el mismo link la próxima vez.
  function renderRoomGate() {
    root.innerHTML = '<div class="screen setup"><h1>Magnate Motors</h1>' +
      '<p class="muted">Multijugador — cada quien juega desde su celular, en vivo.</p>' +
      '<div class="card"><h3>Crear una sala nueva</h3><p class="muted">Genera un código para compartir con tus amigos.</p>' +
      '<button class="btn primary big" id="createRoom">Crear sala</button></div>' +
      '<div class="card"><h3>Unirme con un código</h3>' +
      '<div class="prow"><input type="text" id="joinCode" placeholder="Código de 4 letras" maxlength="10" style="text-transform:uppercase;"></div>' +
      '<button class="btn big" id="joinRoom">Entrar</button></div></div>';
    $("#createRoom").onclick = function () {
      var code = randomRoomCode();
      saveRoom(code);
      connectToRoom(code);
      render();
    };
    $("#joinRoom").onclick = function () {
      var code = ($("#joinCode").value || "").trim().toUpperCase();
      if (!code) { showError("Escribe el código de la sala."); return; }
      saveRoom(code);
      connectToRoom(code);
      render();
    };
  }

  function renderNoHost() {
    root.innerHTML = '<div class="screen"><h1>Magnate Motors</h1>' +
      '<p>No se pudo conectar con la base de datos de la partida. Revisa tu conexión a internet y recarga la página. ' +
      'Si el problema sigue, avísale al anfitrión — puede que falte configurar Firebase.</p></div>';
  }
  function renderChecking() {
    root.innerHTML = '<div class="wait"><div class="wait-card"><div class="pulse"></div><h2>Conectando…</h2><p class="muted">Preparando el estado compartido de la partida.</p></div></div>';
  }

  function waitScreen(title, sub, extraHtml) {
    root.innerHTML = header("Esperando") + '<div class="wait"><div class="wait-card"><div class="pulse"></div>' +
      '<h2>' + esc(title) + '</h2>' + (sub ? '<p class="muted">' + sub + '</p>' : '') + '</div></div>' + (extraHtml || '');
    wireWhoBtn();
  }

  // Devuelve, en orden cronológico, lo que ya hicieron los jugadores en la fase/ronda actual
  // (para que quien espera su turno vea qué decidieron los que ya jugaron).
  function roundPhaseLog() {
    var prefix = "R" + S.round + "F" + S.phase + ": ";
    var entries = (S.log || []).filter(function (l) { return l.indexOf(prefix) === 0; }).map(function (l) { return l.slice(prefix.length); });
    entries.reverse();
    return entries;
  }
  function turnHistoryHtml() {
    var entries = roundPhaseLog();
    if (!entries.length) return '';
    return '<div class="card" style="text-align:left;margin-top:16px;"><h3>Lo que ya hicieron</h3>' +
      entries.map(function (e) { return '<div class="salerow">' + esc(e) + '</div>'; }).join("") + '</div>';
  }

  // ---------------- SETUP ----------------
  function renderSetup() {
    var companyOptions = Object.keys(D.COMPANIES).map(function (cid) {
      var c = D.COMPANIES[cid];
      return '<option value="' + cid + '">' + c.name + " (" + c.sede + ")</option>";
    }).join("");
    root.innerHTML = '<div class="screen setup">' +
      '<h1>Magnate Motors</h1><p class="muted">Multijugador — cada quien juega desde su celular. Configura la partida (3 a 6 jugadores).</p>' +
      '<div id="playerRows"></div>' +
      '<div class="row"><button class="btn" id="addPlayer">+ Añadir jugador</button><button class="btn" id="removePlayer">− Quitar</button></div>' +
      '<button class="btn primary big" id="startGame">Crear partida</button>' +
      '<p class="fine">Al crear la partida, comparte este mismo enlace (ya trae el código de la sala) con los demás jugadores para que cada quien entre desde su celular y elija su nombre.</p>' +
      '</div>';
    var rowsEl = $("#playerRows");
    function rowHtml(i, name) {
      return '<div class="prow" data-i="' + i + '"><input type="text" class="pname" placeholder="Jugador ' + (i + 1) + '" value="' + (name || "") + '">' +
        '<select class="pcompany">' + companyOptions + '</select><label class="botcheck"><input type="checkbox" class="pbot"> CPU</label></div>';
    }
    var count = 4;
    for (var i = 0; i < count; i++) rowsEl.insertAdjacentHTML("beforeend", rowHtml(i));
    rowsEl.querySelectorAll(".pcompany").forEach(function (sel, idx) { sel.selectedIndex = idx % Object.keys(D.COMPANIES).length; });
    $("#addPlayer").onclick = function () {
      var n = rowsEl.querySelectorAll(".prow").length;
      if (n >= 6) return;
      rowsEl.insertAdjacentHTML("beforeend", rowHtml(n));
      rowsEl.querySelectorAll(".pcompany")[n].selectedIndex = n % Object.keys(D.COMPANIES).length;
    };
    $("#removePlayer").onclick = function () {
      var rows = rowsEl.querySelectorAll(".prow");
      if (rows.length <= 3) return;
      rows[rows.length - 1].remove();
    };
    $("#startGame").onclick = function () {
      var rows = rowsEl.querySelectorAll(".prow");
      var used = {}, defs = [], ok = true;
      rows.forEach(function (r) {
        var name = r.querySelector(".pname").value.trim() || r.querySelector(".pname").placeholder;
        var comp = r.querySelector(".pcompany").value;
        var isBot = r.querySelector(".pbot").checked;
        if (used[comp]) ok = false;
        used[comp] = true;
        defs.push({ name: name, companyId: comp, isBot: isBot });
      });
      if (!ok) { showError("Cada jugador debe elegir una empresa distinta."); return; }
      startNewGame(defs);
    };
  }

  function startNewGame(playerDefs) {
    var players = playerDefs.map(function (pd, i) {
      var c = D.COMPANIES[pd.companyId];
      var start = c.startMarket;
      return {
        id: "p" + i, name: pd.name, isBot: !!pd.isBot, companyId: pd.companyId, cash: c.capital,
        acciones: (function () { var o = {}; o[pd.companyId] = c.accionesPropias; return o; })(),
        stockValue: c.accionInicial, stockValueInicial: c.accionInicial,
        factories: [start], offices: [start], inventory: {},
        patentesDesarrolladas: {}, patentes: {}, knowhow: [], koganeUsedThisRound: false,
        marketsDominatedThisRound: [], _devCount: 0
      };
    });
    S = {
      players: players, round: 1, phase: 1, turnOrder: [], turnIndex: 0, log: [],
      events: { active: [] }, revealedEventIds: [], distributionData: {}, stockBids: {},
      companiesInUse: playerDefs.map(function (p) { return p.companyId; }),
      lastSaleResults: null, finished: false,
      dividendVotes: {}, ackSale: {}, ackAdjust: {}, ackEvents: {}, trades: [],
      tradeOffers: [], tradeSeq: 0, pendingMonopoly: []
    };
    computeTurnOrder();
    commit();
  }

  // ---------------- SELECCIÓN DE IDENTIDAD ----------------
  function renderIdentityPicker() {
    root.innerHTML = '<div class="screen">' +
      '<h1>¿Quién eres?</h1><p class="muted">Elige tu jugador en este celular. Solo tú deberías tocar tu nombre.</p>' +
      S.players.filter(function (p) { return !p.isBot; }).map(function (p) {
        var c = D.COMPANIES[p.companyId];
        return '<button class="idbtn" data-id="' + p.id + '">' + esc(p.name) + '<span class="sub">' + c.name + ' · efectivo inicial ' + fmt(p.cash) + '</span></button>';
      }).join("") +
      '<button class="idbtn" data-id="spectator">Solo estoy mirando<span class="sub">Espectador / pantalla compartida</span></button>' +
      '</div>';
    root.querySelectorAll(".idbtn").forEach(function (btn) {
      btn.onclick = function () { setIdentity(btn.dataset.id); render(); };
    });
  }

  // ---------------- FASE 1: PRODUCCIÓN ----------------
  function renderProduction() {
    var actor = currentTurnPlayer();
    var myId = getIdentity();
    if (actor.isBot) { scheduleBot(function () { botProduce(actor); advanceTurn(function () { S.phase = 2; }); }); waitScreen("CPU jugando…", esc(actor.name) + " está decidiendo su producción."); return; }
    if (myId !== actor.id) { waitScreen("Esperando a " + actor.name, "Fase 1 — Producción", turnHistoryHtml()); return; }

    var flags = activeEventFlags();
    var capPer = L.productionCapPerFactory(actor, flags);
    var draftKey = draftKeyFor("prod", actor.id);
    var draft = loadDraft(draftKey);
    var rows = actor.factories.map(function (mid) {
      var m = D.MARKETS[mid], cost = L.productionCost(actor, mid, flags);
      var val = (draft && draft[mid] != null) ? draft[mid] : 0;
      return '<div class="frow" data-m="' + mid + '"><div><b>' + m.name + '</b><span class="muted"> costo $' + cost + '/u · cap fábrica ' + capPer + ' · demanda del mercado ' + m.demanda + '</span></div>' +
        '<input type="number" min="0" max="' + capPer + '" value="' + val + '" class="unitsInput" data-cost="' + cost + '" data-m="' + mid + '"></div>';
    }).join("");
    root.innerHTML = header("Producción") + '<div class="screen"><h2>Tu turno — Producción</h2>' +
      '<p class="muted">Efectivo disponible: ' + fmt(actor.cash) + '</p>' + rows +
      '<div class="totalline" id="totalCost">Costo total: $0</div>' +
      '<button class="btn primary big" id="confirmProd">Confirmar y pagar</button>' + turnHistoryHtml() + '</div>';
    wireWhoBtn();
    function saveDraftNow() {
      var d = {};
      root.querySelectorAll(".unitsInput").forEach(function (inp) { d[inp.dataset.m] = parseInt(inp.value, 10) || 0; });
      saveDraft(draftKey, d);
    }
    function recompute() {
      var total = 0;
      root.querySelectorAll(".unitsInput").forEach(function (inp) { total += (parseInt(inp.value, 10) || 0) * parseInt(inp.dataset.cost, 10); });
      $("#totalCost").textContent = "Costo total: " + fmt(total);
      saveDraftNow();
    }
    recompute();
    root.querySelectorAll(".unitsInput").forEach(function (inp) { inp.oninput = recompute; });
    $("#confirmProd").onclick = function () {
      var total = 0, produced = {};
      root.querySelectorAll(".frow").forEach(function (row) {
        var mid = row.dataset.m, units = parseInt(row.querySelector(".unitsInput").value, 10) || 0;
        var cost = parseInt(row.querySelector(".unitsInput").dataset.cost, 10);
        total += units * cost; produced[mid] = units;
      });
      if (total > actor.cash) { showError("No tienes suficiente efectivo."); return; }
      actor.cash -= total;
      Object.keys(produced).forEach(function (mid) { actor.inventory[mid] = (actor.inventory[mid] || 0) + produced[mid]; });
      log(actor.name + " produjo por " + fmt(total));
      clearDraft(draftKey);
      advanceTurn(function () { S.phase = 2; });
    };
  }

  function advanceTurn(nextPhaseFn) {
    S.turnIndex++;
    if (S.turnIndex >= S.turnOrder.length) { S.turnIndex = 0; nextPhaseFn(); }
    commit();
  }

  var botTimer = null;
  function scheduleBot(fn) {
    if (botTimer) return;
    botTimer = setTimeout(function () {
      botTimer = null;
      try { fn(); } catch (e) { /* decisión de CPU falló; el siguiente render lo reintentará */ }
    }, 900 + Math.random() * 900);
  }

  // ---------------- FASE 2: COMPRA DE PATENTES ----------------
  function renderPatentPurchase() {
    var actor = currentTurnPlayer();
    var myId = getIdentity();
    if (actor.isBot) { scheduleBot(function () { botBuyPatents(actor); advanceTurn(function () { S.phase = 3; }); }); waitScreen("CPU jugando…", esc(actor.name) + " está revisando patentes."); return; }
    if (myId !== actor.id) { waitScreen("Esperando a " + actor.name, "Fase 2 — Compra de patentes", turnHistoryHtml()); return; }

    var offers = [];
    S.players.forEach(function (owner) {
      if (owner.id === actor.id) return;
      Object.keys(D.PATENTES).forEach(function (branch) {
        var devLevels = owner.patenteDevLevels ? owner.patenteDevLevels[branch] || [] : [];
        devLevels.forEach(function (entry) {
          var nivel = entry.nivel, myLevel = actor.patentes[branch] || 0;
          if (myLevel >= nivel || nivel - myLevel !== 1) return;
          offers.push({ branch: branch, nivel: nivel, ownerId: owner.id, ownerName: owner.name, precio: D.PATENTES[branch].niveles[nivel].compra });
        });
      });
    });
    var freeAvailable = D.COMPANIES[actor.companyId].id === "kogane" && !actor.koganeUsedThisRound;
    root.innerHTML = header("Compra de patentes") + '<div class="screen"><h2>Tu turno — Compra de patentes</h2>' +
      (freeAvailable ? '<p class="badge good">Kaizen: tu primera compra esta ronda es gratis</p>' : '') +
      '<p class="muted">Efectivo: ' + fmt(actor.cash) + '</p>' +
      (offers.length === 0 ? '<p class="muted">No hay patentes disponibles todavía.</p>' :
        offers.map(function (o, idx) {
          return '<div class="frow"><div><b>' + D.PATENTES[o.branch].nombre + ' Nv' + o.nivel + '</b><span class="muted"> de ' + esc(o.ownerName) + ' · $' + o.precio + '</span></div>' +
            '<button class="btn small buyPatent" data-idx="' + idx + '">Comprar</button></div>';
        }).join("")) +
      '<button class="btn primary big" id="donePatents">Terminar mi turno</button>' + turnHistoryHtml() + '</div>';
    wireWhoBtn();
    root.querySelectorAll(".buyPatent").forEach(function (btn) {
      btn.onclick = function () {
        var o = offers[parseInt(btn.dataset.idx, 10)];
        var owner = playerById(o.ownerId);
        var price = (freeAvailable && !actor.koganeUsedThisRound) ? 0 : o.precio;
        if (actor.cash < price) { showError("No tienes suficiente efectivo."); return; }
        actor.cash -= price; owner.cash += price; actor.patentes[o.branch] = o.nivel;
        if (price === 0) actor.koganeUsedThisRound = true;
        log(actor.name + " compró " + D.PATENTES[o.branch].nombre + " Nv" + o.nivel + " de " + owner.name + " por $" + price);
        render();
      };
    });
    $("#donePatents").onclick = function () { advanceTurn(function () { S.phase = 3; }); };
  }

  // ---------------- FASE 3: DESARROLLO ----------------
  function renderDevelopment() {
    var actor = currentTurnPlayer();
    var myId = getIdentity();
    if (actor.isBot) { scheduleBot(function () { botDevelop(actor); advanceTurn(function () { S.phase = 4; }); }); waitScreen("CPU jugando…", esc(actor.name) + " está desarrollando tecnología."); return; }
    if (myId !== actor.id) { waitScreen("Esperando a " + actor.name, "Fase 3 — Desarrollo", turnHistoryHtml()); return; }

    var maxDev = L.hasKnow(actor, "plataforma_modular") ? 2 : 1;
    actor._devCount = actor._devCount || 0;
    var patentOptions = [];
    Object.keys(D.PATENTES).forEach(function (branch) {
      var myLevel = actor.patentes[branch] || 0, nextLevel = myLevel + 1;
      if (nextLevel > 5) return;
      var already = S.players.some(function (pl) { return pl.patenteDevLevels && pl.patenteDevLevels[branch] && pl.patenteDevLevels[branch].some(function (e) { return e.nivel === nextLevel; }); });
      if (already) return;
      patentOptions.push({ branch: branch, nivel: nextLevel, costo: D.PATENTES[branch].niveles[nextLevel].desarrollo });
    });
    var knowOptions = D.KNOWHOW.filter(function (k) { return k.ronda <= S.round && !S.players.some(function (pl) { return pl.knowhow.indexOf(k.id) !== -1; }); });

    root.innerHTML = header("Desarrollo") + '<div class="screen"><h2>Tu turno — Desarrollo (' + actor._devCount + '/' + maxDev + ')</h2>' +
      '<p class="muted">Efectivo: ' + fmt(actor.cash) + '</p><h3>Patentes</h3>' +
      (patentOptions.length ? patentOptions.map(function (o, idx) {
        return '<div class="frow"><div><b>' + D.PATENTES[o.branch].nombre + ' Nv' + o.nivel + '</b><span class="muted"> · $' + o.costo + '</span></div>' +
          '<button class="btn small devPatent" data-idx="' + idx + '">Desarrollar</button></div>';
      }).join("") : '<p class="muted">Sin patentes disponibles.</p>') +
      '<h3>Know-How</h3>' +
      (knowOptions.length ? knowOptions.map(function (k, idx) {
        return '<div class="frow"><div><b>' + k.nombre + '</b><span class="muted"> · $' + k.precio + ' — ' + k.desc + '</span></div>' +
          '<button class="btn small devKnow" data-idx="' + idx + '">Desarrollar</button></div>';
      }).join("") : '<p class="muted">Sin Know-How disponible.</p>') +
      '<button class="btn primary big" id="doneDev">Terminar mi turno</button>' + turnHistoryHtml() + '</div>';
    wireWhoBtn();
    root.querySelectorAll(".devPatent").forEach(function (btn) {
      btn.onclick = function () {
        if (actor._devCount >= maxDev) { showError("Ya desarrollaste tu(s) tecnología(s) esta ronda."); return; }
        var o = patentOptions[parseInt(btn.dataset.idx, 10)];
        var cost = L.developmentCost(actor, o.costo);
        if (actor.cash < cost) { showError("No tienes suficiente efectivo."); return; }
        actor.cash -= cost; actor.patentes[o.branch] = o.nivel;
        actor.patenteDevLevels = actor.patenteDevLevels || {}; actor.patenteDevLevels[o.branch] = actor.patenteDevLevels[o.branch] || [];
        actor.patenteDevLevels[o.branch].push({ nivel: o.nivel });
        actor.patentesDesarrolladas[o.branch] = Math.max(actor.patentesDesarrolladas[o.branch] || 0, o.nivel);
        actor._devCount++;
        log(actor.name + " desarrolló " + D.PATENTES[o.branch].nombre + " Nv" + o.nivel + " por $" + cost);
        render();
      };
    });
    root.querySelectorAll(".devKnow").forEach(function (btn) {
      btn.onclick = function () {
        if (actor._devCount >= maxDev) { showError("Ya desarrollaste tu(s) tecnología(s) esta ronda."); return; }
        var k = knowOptions[parseInt(btn.dataset.idx, 10)];
        if (actor.cash < k.precio) { showError("No tienes suficiente efectivo."); return; }
        actor.cash -= k.precio; actor.knowhow.push(k.id); actor._devCount++;
        log(actor.name + " tomó el Know-How " + k.nombre);
        render();
      };
    });
    $("#doneDev").onclick = function () { actor._devCount = 0; advanceTurn(function () { S.phase = 4; }); };
  }

  // ---------------- FASE 4: EXPANSIÓN ----------------
  function renderExpansion() {
    var actor = currentTurnPlayer();
    var myId = getIdentity();
    if (actor.isBot) { scheduleBot(function () { botExpand(actor); advanceTurn(function () { S.phase = 5; S.distributionData = {}; }); }); waitScreen("CPU jugando…", esc(actor.name) + " está evaluando expansión."); return; }
    if (myId !== actor.id) { waitScreen("Esperando a " + actor.name, "Fase 4 — Expansión", turnHistoryHtml()); return; }

    var flags = activeEventFlags();
    var maxFab = L.maxFactories(actor);
    var homeContinent = D.MARKETS[actor.factories[0]] ? D.MARKETS[actor.factories[0]].continente : null;
    var options = Object.keys(D.MARKETS).map(function (mid) {
      var m = D.MARKETS[mid];
      var hasOffice = actor.offices.indexOf(mid) !== -1, hasFactory = actor.factories.indexOf(mid) !== -1;
      var foreign = homeContinent && m.continente !== homeContinent;
      return { mid: mid, m: m, hasOffice: hasOffice, hasFactory: hasFactory, barrera: L.expansionBarrier(actor, mid, foreign, flags) };
    });
    root.innerHTML = header("Expansión") + '<div class="screen"><h2>Tu turno — Expansión</h2>' +
      '<p class="muted">Efectivo: ' + fmt(actor.cash) + ' · Fábricas: ' + actor.factories.length + '/' + maxFab + '</p>' +
      options.map(function (o) {
        var oficinaCost = o.barrera + L.expansionBuildCost(actor, "oficina");
        var fabricaCost = o.barrera + L.expansionBuildCost(actor, "fabrica");
        var presencia = marketPresenceSummary(o.mid).filter(function (l) { return l.id !== actor.id; });
        return '<div class="frow"><div><b>' + o.m.name + '</b><span class="muted"> · ' + o.m.continente + ' · demanda ' + o.m.demanda + ' · tope ' + o.m.tope + '</span>' +
          (o.hasFactory ? '<span class="badge good">fábrica</span>' : o.hasOffice ? '<span class="badge">oficina</span>' : '') +
          (presencia.length ? '<div class="muted" style="margin-top:4px;">Ya presentes: ' + presencia.map(function (l) {
            return esc(l.company) + (l.hasFactory ? ' (fábrica)' : l.hasOffice ? ' (oficina)' : '');
          }).join(", ") + '</div>' : '') +
          '</div><div class="btnpair">' +
          (o.hasOffice || o.hasFactory ? '' : '<button class="btn small expandOffice" data-m="' + o.mid + '">Oficina $' + oficinaCost + '</button>') +
          (o.hasFactory || actor.factories.length >= maxFab ? '' : '<button class="btn small expandFactory" data-m="' + o.mid + '">Fábrica $' + fabricaCost + '</button>') +
          '</div></div>';
      }).join("") + '<button class="btn primary big" id="doneExp">Terminar mi turno</button>' + turnHistoryHtml() + '</div>';
    wireWhoBtn();
    root.querySelectorAll(".expandOffice").forEach(function (btn) {
      btn.onclick = function () {
        var mid = btn.dataset.m, o = options.filter(function (x) { return x.mid === mid; })[0];
        var cost = o.barrera + L.expansionBuildCost(actor, "oficina");
        if (actor.cash < cost) { showError("No tienes suficiente efectivo."); return; }
        actor.cash -= cost; actor.offices.push(mid);
        log(actor.name + " abrió oficina en " + o.m.name + " por $" + cost);
        render();
      };
    });
    root.querySelectorAll(".expandFactory").forEach(function (btn) {
      btn.onclick = function () {
        var mid = btn.dataset.m, o = options.filter(function (x) { return x.mid === mid; })[0];
        if (actor.factories.length >= maxFab) { showError("Ya tienes el máximo de fábricas."); return; }
        var cost = o.barrera + L.expansionBuildCost(actor, "fabrica");
        if (actor.cash < cost) { showError("No tienes suficiente efectivo."); return; }
        actor.cash -= cost; actor.factories.push(mid);
        if (actor.offices.indexOf(mid) === -1) actor.offices.push(mid);
        log(actor.name + " construyó fábrica en " + o.m.name + " por $" + cost);
        render();
      };
    });
    $("#doneExp").onclick = function () { advanceTurn(function () { S.phase = 5; S.distributionData = {}; }); };
  }

  // ---------------- FASE 5: DISTRIBUCIÓN (simultánea) ----------------
  function allSubmitted(map) { return S.players.every(function (p) { return Object.prototype.hasOwnProperty.call(map, p.id); }); }
  function missingNames(map) { return S.players.filter(function (p) { return !Object.prototype.hasOwnProperty.call(map, p.id); }).map(function (p) { return p.name; }); }

  function renderDistribution() {
    var myId = getIdentity();
    // Resolver bots pendientes
    var pendingBot = S.players.filter(function (p) { return p.isBot && !S.distributionData[p.id]; })[0];
    if (pendingBot) { scheduleBot(function () { botDistribute(pendingBot); maybeResolveDistribution(); }); }

    if (allSubmitted(S.distributionData)) { waitScreen("Resolviendo ventas…", "Todos enviaron su distribución."); maybeResolveDistribution(); return; }

    if (myId === "spectator" || myId === null) {
      waitScreen("Fase secreta en curso", "Faltan por enviar: " + missingNames(S.distributionData).join(", "));
      return;
    }
    var me = playerById(myId);
    if (!me) { waitScreen("Esperando…", ""); return; }
    if (S.distributionData[myId]) {
      waitScreen("Ya enviaste tu distribución", "Faltan: " + missingNames(S.distributionData).join(", "));
      return;
    }

    var totalInv = Object.keys(me.inventory).reduce(function (s, k) { return s + me.inventory[k]; }, 0);
    var presenceMarkets = me.offices.slice();
    var extra = L.extraUnits(me, activeEventFlags());
    var invByMarket = Object.keys(me.inventory).filter(function (mid) { return me.inventory[mid] > 0; });
    var invBreakdownHtml = '<div class="card"><h3>Tu producción disponible (dónde está)</h3>' +
      (invByMarket.length ? invByMarket.map(function (mid) {
        var nombre = mid === "_carry" ? "Sobrante de ronda anterior" : (D.MARKETS[mid] ? D.MARKETS[mid].name : mid);
        return '<div class="salerow"><b>' + esc(nombre) + '</b>: ' + me.inventory[mid] + ' unidad(es)</div>';
      }).join("") : '<p class="muted">No tienes inventario.</p>') +
      '<div class="totalline">Total: ' + totalInv + ' unidades</div></div>';
    var draftKey = draftKeyFor("dist", myId);
    var draft = loadDraft(draftKey) || {};
    root.innerHTML = header("Distribución (secreta)") + '<div class="screen"><h2>Tu distribución (solo tú la ves)</h2>' +
      invBreakdownHtml +
      '<p class="muted">Elige cuánto vender y a qué precio en cada mercado donde tienes oficina:</p>' +
      presenceMarkets.map(function (mid) {
        var m = D.MARKETS[mid];
        var dv = (draft.alloc && draft.alloc[mid]) || {};
        return '<div class="frow dist-row" data-m="' + mid + '"><div><b>' + m.name + '</b><span class="muted"> precio máx $' + m.precioMax + ' · demanda tope ' + m.tope + '</span></div>' +
          '<input type="number" min="0" class="distUnits" placeholder="unid." value="' + (dv.unidades || '') + '"><input type="number" min="0" max="' + m.precioMax + '" class="distPrice" placeholder="precio" value="' + (dv.precio || '') + '"></div>';
      }).join("") +
      (extra > 0 ? '<p class="muted">Tienes ' + extra + ' unidades extra — elige UN mercado:</p><select id="extraMarket"><option value="">(ninguno)</option>' +
        presenceMarkets.map(function (mid) { return '<option value="' + mid + '"' + (draft.extraMarket === mid ? ' selected' : '') + '>' + D.MARKETS[mid].name + '</option>'; }).join("") + '</select>' : '') +
      '<div class="totalline" id="distTotal">Traslado a pagar: $0</div>' +
      '<button class="btn primary big" id="confirmDist">Confirmar (secreto) y enviar</button></div>';
    wireWhoBtn();

    function readAlloc() {
      var alloc = {};
      root.querySelectorAll(".dist-row").forEach(function (row) {
        var mid = row.dataset.m, u = parseInt(row.querySelector(".distUnits").value, 10) || 0, pr = parseInt(row.querySelector(".distPrice").value, 10) || 0;
        if (u > 0) alloc[mid] = { unidades: u, precio: pr };
      });
      return alloc;
    }
    function saveDraftNow() {
      var extraSel = $("#extraMarket");
      saveDraft(draftKey, { alloc: readAlloc(), extraMarket: extraSel ? extraSel.value : "" });
    }
    root.querySelectorAll(".distUnits,.distPrice").forEach(function (inp) {
      inp.oninput = function () { $("#distTotal").textContent = "Traslado a pagar: " + fmt(transportTotalForAlloc(me, readAlloc())); saveDraftNow(); };
    });
    var extraSelEl = $("#extraMarket");
    if (extraSelEl) extraSelEl.onchange = saveDraftNow;
    $("#distTotal").textContent = "Traslado a pagar: " + fmt(transportTotalForAlloc(me, readAlloc()));
    $("#confirmDist").onclick = function () {
      var alloc = readAlloc();
      var totalAsignado = Object.keys(alloc).reduce(function (s, k) { return s + alloc[k].unidades; }, 0);
      if (totalAsignado > totalInv) { showError("Estás asignando más unidades de las que tienes."); return; }
      for (var mid in alloc) { if (alloc[mid].precio > D.MARKETS[mid].precioMax) { showError(D.MARKETS[mid].name + ": el precio no puede superar $" + D.MARKETS[mid].precioMax); return; } }
      var transporte = transportTotalForAlloc(me, alloc);
      if (transporte > me.cash) { showError("No tienes suficiente efectivo para el traslado."); return; }
      me.cash -= transporte;
      var extraSel = $("#extraMarket");
      S.distributionData[me.id] = { alloc: alloc, extraMarket: extraSel ? extraSel.value : "", unassigned: totalInv - totalAsignado };
      log(me.name + " distribuyó su inventario (secreto)");
      clearDraft(draftKey);
      if (allSubmitted(S.distributionData)) { resolveSalesAndCommit(); } else { commit(); }
    };
  }

  function maybeResolveDistribution() {
    if (allSubmitted(S.distributionData)) resolveSalesAndCommit(); else commit();
  }

  function resolveSalesAndCommit() {
    computeSales();
    S.phase = 6;
    S.ackSale = {};
    commit();
  }

  function computeSales() {
    var flags = activeEventFlags();
    var reqReg = regulatoryRequirement();
    var porMercado = {}, ventasTotalesPorJugador = {};
    S.players.forEach(function (p) { ventasTotalesPorJugador[p.id] = 0; p.marketsDominatedThisRound = []; p._remateCount = 0; });

    Object.keys(D.MARKETS).forEach(function (mid) {
      var demanda = marketDemand(mid);
      var offers = [];
      S.players.forEach(function (p) {
        var dd = S.distributionData[p.id];
        if (!dd || !dd.alloc[mid]) return;
        var a = dd.alloc[mid];
        var tieneFabrica = p.factories.indexOf(mid) !== -1;
        var cap = L.marketCap(p, mid, tieneFabrica);
        var comp = D.COMPANIES[p.companyId];
        var unidadesExtra = (dd.extraMarket === mid) ? L.extraUnits(p, flags) : 0;
        if (comp.id === "imperial" && p.offices.indexOf(mid) !== -1) unidadesExtra += 1;
        offers.push({
          playerId: p.id, name: p.name, unidades: a.unidades, precio: a.precio, cap: cap, tieneFabrica: tieneFabrica,
          accesoriosNivel: L.patentLevel(p, "accesorios"), valorAccion: p.stockValue, unidadesExtra: unidadesExtra,
          bonoPrecio: L.priceBonusPerUnit(p, mid, flags), marcaPremium: L.hasKnow(p, "marca_premium")
        });
      });
      if (offers.length === 0) { porMercado[mid] = { demanda: demanda, detalle: [], dominante: null }; return; }
      var incumplio = {};
      offers.forEach(function (o) { var p = playerById(o.playerId); if (L.regulatoryLevel(p) < reqReg) incumplio[o.playerId] = true; });
      var resolved = L.resolveMarketSale(offers, demanda, incumplio);
      var detalle = offers.map(function (o) {
        var p = playerById(o.playerId);
        var vendidas = resolved.ventas[o.playerId] || 0, ingreso = resolved.ingresos[o.playerId] || 0, remate = resolved.remate[o.playerId] || 0;
        p.cash += ingreso; ventasTotalesPorJugador[o.playerId] += ingreso;
        if (remate > 0) { p.cash += L.remateValue(mid, remate); p._remateCount += remate; }
        if (resolved.dominante === o.playerId) p.marketsDominatedThisRound.push(mid);
        return { name: o.name, vendidas: vendidas, precio: o.precio, bono: o.bonoPrecio, ingreso: ingreso, remate: remate };
      });
      porMercado[mid] = { demanda: demanda, detalle: detalle, dominante: resolved.dominante ? playerById(resolved.dominante).name : null };
    });

    S.players.forEach(function (p) {
      var dd = S.distributionData[p.id];
      var asignadoTotal = 0;
      if (dd) Object.keys(dd.alloc).forEach(function (mid) { asignadoTotal += dd.alloc[mid].unidades; });
      var invTotal = Object.keys(p.inventory).reduce(function (s, k) { return s + p.inventory[k]; }, 0);
      var sinAsignar = invTotal - asignadoTotal;
      if (L.hasKnow(p, "red_distribucion")) { p.inventory = {}; if (sinAsignar > 0) p.inventory["_carry"] = sinAsignar; }
      else { p.inventory = {}; }
    });

    S.lastSaleResults = { porMercado: porMercado, ventasTotalesPorJugador: ventasTotalesPorJugador };
    S.distributionData = {};
  }

  // ---------------- FASE 6: VENTA (resultado, ya calculado) ----------------
  function renderSaleResolution() {
    var myId = getIdentity();
    var pendingBot = S.players.filter(function (p) { return p.isBot && !S.ackSale[p.id]; })[0];
    if (pendingBot) { scheduleBot(function () { S.ackSale[pendingBot.id] = true; maybeAdvanceFromSale(); }); }
    var iAcked = myId && myId !== "spectator" && S.ackSale[myId];
    var missing = S.players.filter(function (p) { return !S.ackSale[p.id]; }).map(function (p) { return p.name; });
    var res = S.lastSaleResults;
    root.innerHTML = header("Venta") + '<div class="screen"><h2>Resultados de venta — Ronda ' + S.round + '</h2>' +
      Object.keys(res.porMercado).map(function (mid) {
        var m = D.MARKETS[mid], r = res.porMercado[mid];
        return '<div class="card"><h3>' + m.name + ' <span class="muted">(demanda ' + r.demanda + ', tope ' + m.tope + ')</span></h3>' +
          r.detalle.map(function (d) { return '<div class="salerow"><b>' + esc(d.name) + '</b>: ' + d.vendidas + ' u. a $' + d.precio + (d.bono ? ('+' + d.bono) : '') + ' → ' + fmt(d.ingreso) + (d.remate ? (' · remate ' + d.remate + ' u.') : '') + '</div>'; }).join("") +
          (r.dominante ? '<div class="badge good">Domina: ' + esc(r.dominante) + '</div>' : '') + '</div>';
      }).join("") +
      '<div class="card"><h3>Resumen por jugador</h3>' + S.players.map(function (p) {
        return '<div class="salerow"><b>' + esc(p.name) + '</b>: ventas ' + fmt(res.ventasTotalesPorJugador[p.id] || 0) + ' · efectivo ahora ' + fmt(p.cash) + '</div>';
      }).join("") + '</div>' +
      (myId === "spectator" || myId === null ? '<p class="muted">Esperando a los jugadores…</p>' :
        iAcked ? '<p class="muted">Listo. Esperando a: ' + missing.join(", ") + '</p>' :
        '<button class="btn primary big" id="toAdjust">Listo, continuar a ajuste de acción</button>') +
      '</div>';
    wireWhoBtn();
    var btn = $("#toAdjust");
    if (btn) btn.onclick = function () { S.ackSale[myId] = true; maybeAdvanceFromSale(); };
  }

  function maybeAdvanceFromSale() {
    if (!S.players.every(function (p) { return S.ackSale[p.id]; })) { commit(); return; }
    S.ackAdjust = {};
    if (dividendVotesComplete()) computeAdjustment();
    S.phase = 7;
    commit();
  }

  // ---------------- FASE 7: VOTO DE DIVIDENDOS + AJUSTE (resultado) ----------------
  function dividendCompaniesNeeded() {
    if (S.round === 5) return []; // ronda 5: el dividendo es obligatorio, no se vota
    var res = [], byCompany = {};
    S.players.forEach(function (p) { byCompany[p.companyId] = byCompany[p.companyId] || []; byCompany[p.companyId].push(p); });
    Object.keys(byCompany).forEach(function (cid) {
      var holders = S.players.filter(function (p) { return (p.acciones[cid] || 0) > 0; });
      if (holders.length < 2) return;
      var ceo = byCompany[cid].slice().sort(function (a, b) { return (b.acciones[cid] || 0) - (a.acciones[cid] || 0); })[0];
      var totalVentas = (S.lastSaleResults && S.lastSaleResults.ventasTotalesPorJugador[ceo.id]) || 0;
      if (totalVentas <= 0) return;
      res.push({ cid: cid, holders: holders, ceo: ceo });
    });
    return res;
  }
  function dividendVotesComplete() {
    return dividendCompaniesNeeded().every(function (c) {
      var votes = S.dividendVotes[c.cid] || {};
      return c.holders.every(function (h) { return Object.prototype.hasOwnProperty.call(votes, h.id); });
    });
  }
  // Voto de dividendos de la CPU: como accionista minoritario siempre le conviene cobrar, así
  // que vota sí. Si es el CEO (mayoría) quien paga, el dividendo le cuesta lo que reparte a los
  // demás accionistas — vota no si ese costo es demasiado alto frente a su efectivo; si es
  // manejable, vota sí porque además sube el valor de su acción.
  function botDividendVote(p, cid) {
    var holders = S.players.filter(function (pl) { return (pl.acciones[cid] || 0) > 0; });
    if (!holders.length) return "si";
    var ceo = holders.slice().sort(function (a, b) { return (b.acciones[cid] || 0) - (a.acciones[cid] || 0); })[0];
    if (ceo.id !== p.id) return "si";
    var totalVentas = (S.lastSaleResults && S.lastSaleResults.ventasTotalesPorJugador[p.id]) || 0;
    if (totalVentas <= 0) return "no";
    var accionesEnManos = holders.reduce(function (s, h) { return s + (h.acciones[cid] || 0); }, 0);
    var perShare = L.dividendPerShare(totalVentas, accionesEnManos);
    var costoNeto = perShare * (accionesEnManos - (p.acciones[cid] || 0));
    return costoNeto <= Math.max(5, p.cash * 0.12) ? "si" : "no";
  }

  function renderDividendVote() {
    var myId = getIdentity();
    var companies = dividendCompaniesNeeded();
    var pendingBotVote = null;
    companies.forEach(function (c) {
      c.holders.forEach(function (h) {
        if (!pendingBotVote && h.isBot && !((S.dividendVotes[c.cid] || {})[h.id])) pendingBotVote = { cid: c.cid, id: h.id };
      });
    });
    if (pendingBotVote) {
      var pv = pendingBotVote;
      scheduleBot(function () {
        S.dividendVotes[pv.cid] = S.dividendVotes[pv.cid] || {};
        S.dividendVotes[pv.cid][pv.id] = botDividendVote(playerById(pv.id), pv.cid);
        if (dividendVotesComplete()) computeAdjustment();
        commit();
      });
    }
    if (myId === "spectator" || myId === null) { waitScreen("Votación de dividendos", "Los accionistas están decidiendo si repartir dividendos."); return; }
    var myCompanies = companies.filter(function (c) {
      return c.holders.some(function (h) { return h.id === myId; }) && !((S.dividendVotes[c.cid] || {})[myId]);
    });
    if (!myCompanies.length) {
      var pending = [];
      companies.forEach(function (c) { c.holders.forEach(function (h) { if (!((S.dividendVotes[c.cid] || {})[h.id])) pending.push(h.name + " (" + D.COMPANIES[c.cid].name + ")"); }); });
      waitScreen("Ya votaste", pending.length ? "Falta: " + pending.join(", ") : "Calculando resultados…");
      return;
    }
    var me = playerById(myId);
    root.innerHTML = header("Ajuste de acción") + '<div class="screen"><h2>Dividendos — tu voto (secreto)</h2>' +
      '<p class="muted">Hay 2 o más accionistas en estas empresas. Como accionista, decide si cada una reparte dividendo esta ronda.</p>' +
      myCompanies.map(function (c) {
        return '<div class="frow" data-c="' + c.cid + '"><div><b>' + D.COMPANIES[c.cid].name + '</b><span class="muted"> · tienes ' + (me.acciones[c.cid] || 0) + ' acción(es)</span></div>' +
          '<div class="btnpair"><button class="btn small voteYes" data-c="' + c.cid + '">Sí, repartir</button><button class="btn small voteNo" data-c="' + c.cid + '">No repartir</button></div></div>';
      }).join("") + '</div>';
    wireWhoBtn();
    function castVote(cid, val) {
      S.dividendVotes[cid] = S.dividendVotes[cid] || {};
      S.dividendVotes[cid][myId] = val;
      log(me.name + " votó " + (val === "si" ? "SÍ" : "NO") + " al dividendo de " + D.COMPANIES[cid].name);
      if (dividendVotesComplete()) computeAdjustment();
      commit();
    }
    root.querySelectorAll(".voteYes").forEach(function (btn) { btn.onclick = function () { castVote(btn.dataset.c, "si"); }; });
    root.querySelectorAll(".voteNo").forEach(function (btn) { btn.onclick = function () { castVote(btn.dataset.c, "no"); }; });
  }

  function computeAdjustment() {
    var continentDominance = {};
    D.CONTINENTES.forEach(function (c) { continentDominance[c] = {}; });
    S.players.forEach(function (p) { p.marketsDominatedThisRound.forEach(function (mid) { var cont = D.MARKETS[mid].continente; continentDominance[cont][p.id] = (continentDominance[cont][p.id] || 0) + 1; }); });
    var continentLeader = {};
    D.CONTINENTES.forEach(function (c) {
      var entries = Object.keys(continentDominance[c]).map(function (pid) { return { pid: pid, n: continentDominance[c][pid] }; });
      entries.sort(function (a, b) { return b.n - a.n; });
      if (entries.length && (entries.length === 1 || entries[0].n > entries[1].n)) continentLeader[c] = entries[0].pid;
    });
    S.players.forEach(function (p) {
      var delta = 0, reasons = [];
      var domCount = p.marketsDominatedThisRound.length;
      if (domCount > 0) { delta += domCount; reasons.push(domCount + " mercado(s) dominado(s) (+" + domCount + ")"); }
      var contsWon = D.CONTINENTES.filter(function (c) { return continentLeader[c] === p.id; });
      if (contsWon.length > 0) { delta += contsWon.length; reasons.push("mayoría en " + contsWon.length + " continente(s) (+" + contsWon.length + ")"); }
      if (contsWon.length === 5) { delta += 3; reasons.push("dominio en los 5 continentes (+3)"); }
      var presenceNoSale = 0;
      p.offices.forEach(function (mid) { /* distributionData ya se limpió; usamos el resumen de venta como proxy */ });
      var remateCount = p._remateCount || 0;
      if (remateCount >= 5) { delta -= 2; reasons.push("rematar 5+ (-2)"); } else if (remateCount >= 3) { delta -= 1; reasons.push("rematar 3-4 (-1)"); }
      if (S.round === 5) {
        var subsidio = S.events.active.filter(function (e) { return e.tipo === "subsidiosVerdes"; })[0];
        if (subsidio && L.patentLevel(p, "motor") >= subsidio.nivelMinimo) { delta += subsidio.valor; reasons.push("Subsidios verdes (+" + subsidio.valor + ")"); }
      }
      p._stockDelta = delta; p._adjustReasons = reasons; p._dividendPaid = false; p._dividendReceived = 0;
    });
    var byCompany = {};
    S.players.forEach(function (p) { byCompany[p.companyId] = byCompany[p.companyId] || []; byCompany[p.companyId].push(p); });
    Object.keys(byCompany).forEach(function (cid) {
      var holders = byCompany[cid];
      var ceo = holders.slice().sort(function (a, b) { return (b.acciones[cid] || 0) - (a.acciones[cid] || 0); })[0];
      var totalVentas = S.lastSaleResults.ventasTotalesPorJugador[ceo.id] || 0;
      var accionesEnManos = 0; S.players.forEach(function (p) { accionesEnManos += (p.acciones[cid] || 0); });
      var votantes = S.players.filter(function (p) { return (p.acciones[cid] || 0) > 0; });
      var pagar;
      if (votantes.length <= 1) pagar = false;
      else if (S.round === 5) pagar = true;
      else if (totalVentas <= 0) pagar = false;
      else {
        var votes = S.dividendVotes[cid] || {}, yes = 0;
        votantes.forEach(function (p) { if (votes[p.id] === "si") yes += (p.acciones[cid] || 0); });
        pagar = yes >= (accionesEnManos - yes);
      }
      if (pagar && totalVentas > 0) {
        var perShare = L.dividendPerShare(totalVentas, accionesEnManos);
        var totalPagado = perShare * accionesEnManos;
        // El dividendo sale de lo que la empresa (su CEO) ya ganó en ventas esta ronda —
        // no es dinero nuevo del "banco general". El CEO se queda con su propia parte.
        ceo.cash -= totalPagado;
        votantes.forEach(function (p) { var recibido = perShare * (p.acciones[cid] || 0); p.cash += recibido; p._dividendPaid = true; p._dividendReceived = recibido; });
        ceo._stockDelta += 2; ceo._adjustReasons.push("Dividendo repartido (+2)");
      } else { ceo._stockDelta -= 1; ceo._adjustReasons.push("Sin dividendo (-1)"); }
    });
    S.players.forEach(function (p) { p.stockValue = Math.max(1, p.stockValue + p._stockDelta); });
  }

  function renderAdjustment() {
    var myId = getIdentity();
    var pendingBot = S.players.filter(function (p) { return p.isBot && !S.ackAdjust[p.id]; })[0];
    if (pendingBot) { scheduleBot(function () { S.ackAdjust[pendingBot.id] = true; maybeAdvanceFromAdjust(); }); }
    var iAcked = myId && myId !== "spectator" && S.ackAdjust[myId];
    var missing = S.players.filter(function (p) { return !S.ackAdjust[p.id]; }).map(function (p) { return p.name; });
    root.innerHTML = header("Ajuste de acción") + '<div class="screen"><h2>Ajuste de valor de acción y dividendos</h2>' +
      S.players.map(function (p) {
        return '<div class="card"><h3>' + esc(p.name) + ' (' + D.COMPANIES[p.companyId].name + ')</h3>' +
          '<div>Valor de acción: $' + p.stockValue + ' <span class="muted">(' + (p._stockDelta >= 0 ? "+" : "") + p._stockDelta + ')</span></div>' +
          '<div class="muted">' + (p._adjustReasons || []).join(" · ") + '</div>' +
          (p._dividendPaid ? '<div class="badge good">Dividendo recibido: ' + fmt(p._dividendReceived || 0) + '</div>' : '') + '</div>';
      }).join("") +
      (myId === "spectator" || myId === null ? '<p class="muted">Esperando a los jugadores…</p>' :
        iAcked ? '<p class="muted">Listo. Esperando a: ' + missing.join(", ") + '</p>' :
        '<button class="btn primary big" id="toNext">Continuar</button>') +
      '</div>';
    wireWhoBtn();
    var btn = $("#toNext");
    if (btn) btn.onclick = function () { S.ackAdjust[myId] = true; maybeAdvanceFromAdjust(); };
  }
  function maybeAdvanceFromAdjust() {
    if (!S.players.every(function (p) { return S.ackAdjust[p.id]; })) { commit(); return; }
    if (S.round === 5) { finishGame(); } else { S.phase = 8; S.stockBids = {}; commit(); }
  }

  // La CPU también participa en la subasta de acciones: reserva parte de su efectivo y puja
  // por empresas baratas (buena relación valor/costo) que aún tengan acciones disponibles,
  // ofreciendo el valor oficial de la acción (sin sobrepujar) para no arriesgar de más.
  function botStockBids(p) {
    var bids = [];
    var budget = Math.floor(p.cash * 0.5);
    var held = {};
    S.companiesInUse.forEach(function (cid) {
      held[cid] = S.players.reduce(function (s, pl) { return s + (pl.acciones[cid] || 0); }, 0);
    });
    var candidates = S.companiesInUse.map(function (cid) {
      var owner = S.players.filter(function (pl) { return pl.companyId === cid; })[0];
      var value = owner ? owner.stockValue : 10;
      var avail = 10 - (held[cid] || 0);
      return { cid: cid, value: value, avail: avail };
    }).filter(function (c) { return c.avail > 0 && c.value > 0 && c.value <= budget; });
    candidates.sort(function (a, b) { return a.value - b.value; }); // prioriza las más baratas
    candidates.forEach(function (c) {
      if (budget < c.value) return;
      var maxByBudget = Math.floor(budget / c.value);
      var n = Math.min(c.avail, maxByBudget, 2);
      if (n <= 0) return;
      bids.push({ cid: c.cid, n: n, price: c.value });
      budget -= n * c.value;
    });
    return bids;
  }

  // ---------------- FASE 8: MERCADO ACCIONARIO (simultánea) ----------------
  function renderStockMarket() {
    var myId = getIdentity();
    var pendingBot = S.players.filter(function (p) { return p.isBot && !S.stockBids[p.id]; })[0];
    if (pendingBot) { scheduleBot(function () { S.stockBids[pendingBot.id] = botStockBids(pendingBot); maybeResolveStock(); }); }
    if (allSubmitted(S.stockBids)) { waitScreen("Resolviendo subasta…", ""); maybeResolveStock(); return; }
    if (myId === "spectator" || myId === null) { waitScreen("Subasta de acciones en curso", "Faltan: " + missingNames(S.stockBids).join(", ")); return; }
    var me = playerById(myId);
    if (!me) { waitScreen("Esperando…", ""); return; }
    if (S.stockBids[myId]) { waitScreen("Ya enviaste tu papeleta", "Faltan: " + missingNames(S.stockBids).join(", ")); return; }

    var sharesInPlay = {}, companyValues = {};
    Object.keys(D.COMPANIES).forEach(function (cid) {
      if (S.companiesInUse.indexOf(cid) === -1) return;
      var held = S.players.reduce(function (s, pl) { return s + (pl.acciones[cid] || 0); }, 0);
      sharesInPlay[cid] = 10 - held;
    });
    S.players.forEach(function (pl) { companyValues[pl.companyId] = pl.stockValue; });

    var draftKey = draftKeyFor("stock", myId);
    var draft = loadDraft(draftKey) || {};
    root.innerHTML = header("Mercado accionario") + '<div class="screen"><h2>Tu papeleta (secreta)</h2>' +
      '<p class="muted">Efectivo: ' + fmt(me.cash) + '</p>' +
      Object.keys(companyValues).map(function (cid) {
        var band = L.bidBand(companyValues[cid]);
        var dv = draft[cid] || {};
        return '<div class="frow"><div><b>' + D.COMPANIES[cid].name + '</b><span class="muted"> valor $' + companyValues[cid] + ' · disp. ' + sharesInPlay[cid] + ' · banda ±$' + band + '</span></div>' +
          '<input type="number" min="0" class="bidShares" data-c="' + cid + '" placeholder="# acc." style="width:70px" value="' + (dv.n || '') + '">' +
          '<input type="number" class="bidPrice" data-c="' + cid + '" placeholder="precio" style="width:70px" value="' + (dv.price != null ? dv.price : '') + '"></div>';
      }).join("") + '<button class="btn primary big" id="submitBid">Enviar papeleta (secreta)</button></div>';
    wireWhoBtn();
    function saveDraftNow() {
      var d = {};
      root.querySelectorAll(".bidShares").forEach(function (inp) {
        var cid = inp.dataset.c;
        var priceInp = root.querySelector('.bidPrice[data-c="' + cid + '"]');
        d[cid] = { n: parseInt(inp.value, 10) || 0, price: priceInp && priceInp.value !== "" ? parseInt(priceInp.value, 10) || 0 : "" };
      });
      saveDraft(draftKey, d);
    }
    root.querySelectorAll(".bidShares,.bidPrice").forEach(function (inp) { inp.oninput = saveDraftNow; });
    $("#submitBid").onclick = function () {
      var bids = [], invalid = false;
      root.querySelectorAll(".bidShares").forEach(function (inp) {
        var cid = inp.dataset.c, n = parseInt(inp.value, 10) || 0;
        if (n <= 0) return;
        var price = parseInt(root.querySelector('.bidPrice[data-c="' + cid + '"]').value, 10) || 0;
        var band = L.bidBand(companyValues[cid]);
        if (Math.abs(price - companyValues[cid]) > band) { showError(D.COMPANIES[cid].name + ": el precio debe estar dentro de ±$" + band); invalid = true; return; }
        bids.push({ cid: cid, n: n, price: price });
      });
      if (invalid) return;
      S.stockBids[me.id] = bids;
      log(me.name + " envió su papeleta de acciones (secreta)");
      clearDraft(draftKey);
      if (allSubmitted(S.stockBids)) { resolveStockAndEvents(); } else { commit(); }
    };
  }

  function maybeResolveStock() { if (allSubmitted(S.stockBids)) resolveStockAndEvents(); else commit(); }

  function resolveStockMarket() {
    var sharesAvail = {}, companyValues = {};
    Object.keys(D.COMPANIES).forEach(function (cid) {
      if (S.companiesInUse.indexOf(cid) === -1) return;
      var held = S.players.reduce(function (s, pl) { return s + (pl.acciones[cid] || 0); }, 0);
      sharesAvail[cid] = 10 - held;
    });
    S.players.forEach(function (pl) { companyValues[pl.companyId] = pl.stockValue; });
    var companiesOrdered = Object.keys(companyValues).sort(function (a, b) { return companyValues[a] - companyValues[b]; });
    companiesOrdered.forEach(function (cid) {
      var allBids = [];
      S.players.forEach(function (p) {
        (S.stockBids[p.id] || []).filter(function (b) { return b.cid === cid; }).forEach(function (b) { allBids.push({ playerId: p.id, n: b.n, price: b.price }); });
      });
      allBids = allBids.filter(function (b) {
        var p = playerById(b.playerId);
        var totalPapeleta = (S.stockBids[b.playerId] || []).reduce(function (s, x) { return s + x.n * x.price; }, 0);
        return p.cash >= totalPapeleta;
      });
      allBids.sort(function (a, b) { return b.price - a.price; });
      var remaining = sharesAvail[cid], lastPrice = companyValues[cid];
      allBids.forEach(function (b) {
        if (remaining <= 0) return;
        var take = Math.min(b.n, remaining);
        var p = playerById(b.playerId);
        var cost = take * b.price;
        if (p.cash < cost) return;
        p.cash -= cost; p.acciones[cid] = (p.acciones[cid] || 0) + take; remaining -= take; lastPrice = b.price;
        log(p.name + " compró " + take + " acción(es) de " + D.COMPANIES[cid].name + " a $" + b.price);
      });
      S.players.forEach(function (p) { if (p.companyId === cid) p.stockValue = lastPrice; });
    });
  }

  function stockSellCommission(stockValue) { return stockValue < 20 ? 1 : (stockValue <= 30 ? 2 : 3); }
  function companyStockValue(cid) {
    var owner = S.players.filter(function (p) { return p.companyId === cid; })[0];
    return owner ? owner.stockValue : 10;
  }

  // Regla antimonopolio (libro de reglas): "Controlas tu empresa mientras tengas más acciones
  // que cualquier otro jugador. Quien controle dos o más empresas al cierre de la fase debe
  // quedarse con una y vender las demás a jugadores sin empresa, llevándose de la que suelta
  // una oficina o una tecnología."
  // Se detecta al cierre de la Fase 8 (mercado accionario). El propio jugador decide con cuál
  // empresa se queda, elige su recompensa (oficina o tecnología de la empresa que suelta), y
  // recién entonces se vende el exceso de acciones y se pasa a eventos (Fase 9).
  function detectMonopolyConflicts() {
    var controllers = {};
    S.companiesInUse.forEach(function (cid) {
      var bestId = null, bestN = 0, tie = false;
      S.players.forEach(function (p) {
        var n = p.acciones[cid] || 0;
        if (n > bestN) { bestN = n; bestId = p.id; tie = false; }
        else if (n > 0 && n === bestN) { tie = true; }
      });
      controllers[cid] = (bestN > 0 && !tie) ? bestId : null;
    });
    var byPlayer = {};
    Object.keys(controllers).forEach(function (cid) {
      var pid = controllers[cid];
      if (pid) { byPlayer[pid] = byPlayer[pid] || []; byPlayer[pid].push(cid); }
    });
    var pending = [];
    Object.keys(byPlayer).forEach(function (pid) {
      if (byPlayer[pid].length >= 2) pending.push({ playerId: pid, cids: byPlayer[pid], keep: null, rewardPending: [], rewards: {} });
    });
    return pending;
  }

  // Vende el exceso de acciones de una empresa que el jugador suelta (hasta quedar por debajo
  // del segundo accionista) y paga la recompensa en efectivo con la comisión del libro.
  function sellExcessForMonopoly(p, cid) {
    var otherHoldings = S.players.filter(function (x) { return x.id !== p.id; }).map(function (x) { return x.acciones[cid] || 0; });
    var second = otherHoldings.length ? Math.max.apply(null, otherHoldings) : 0;
    var have = p.acciones[cid] || 0;
    var sell = Math.max(0, have - second);
    if (sell <= 0) return 0;
    var stockValue = companyStockValue(cid);
    var comision = stockSellCommission(stockValue);
    var ingreso = Math.max(0, sell * stockValue - comision);
    p.acciones[cid] = have - sell;
    p.cash += ingreso;
    log(p.name + " vendió " + sell + " acción(es) de " + D.COMPANIES[cid].name + " al mercado por " + fmt(ingreso) + " (comisión $" + comision + ") — regla antimonopolio");
    return ingreso;
  }

  // Opciones de recompensa disponibles al soltar una empresa: cada oficina que tenga el dueño
  // original de esa empresa y que el jugador todavía no tenga, más una opción por cada rama de
  // patente que el jugador no tenga al máximo. El jugador elige UNA.
  function monopolyRewardOptions(p, cidGiven) {
    var opts = [];
    var owner = S.players.filter(function (x) { return x.companyId === cidGiven; })[0];
    if (owner) {
      owner.offices.filter(function (mid) { return p.offices.indexOf(mid) === -1; }).forEach(function (mid) {
        opts.push({ key: "oficina:" + mid, type: "oficina", mid: mid, label: "Oficina en " + D.MARKETS[mid].name });
      });
    }
    Object.keys(D.PATENTES).filter(function (b) { return (p.patentes[b] || 0) < 5; }).forEach(function (b) {
      var next = (p.patentes[b] || 0) + 1;
      opts.push({ key: "tech:" + b, type: "tech", branch: b, label: D.PATENTES[b].nombre + " → Nv" + next });
    });
    return opts;
  }
  function applyMonopolyReward(p, cidGiven, optKey) {
    var opts = monopolyRewardOptions(p, cidGiven);
    var opt = opts.filter(function (o) { return o.key === optKey; })[0] || opts[0];
    if (!opt) return null;
    if (opt.type === "oficina") {
      p.offices.push(opt.mid);
      log(p.name + " se lleva una oficina en " + D.MARKETS[opt.mid].name + " de " + D.COMPANIES[cidGiven].name + " como recompensa (regla antimonopolio)");
    } else {
      p.patentes[opt.branch] = (p.patentes[opt.branch] || 0) + 1;
      log(p.name + " se lleva tecnología (" + D.PATENTES[opt.branch].nombre + " Nv" + p.patentes[opt.branch] + ") de " + D.COMPANIES[cidGiven].name + " como recompensa (regla antimonopolio)");
    }
    return opt.label;
  }

  function resolveMonopolyChoice(pid, keepCid) {
    var conflict = (S.pendingMonopoly || []).filter(function (c) { return c.playerId === pid; })[0];
    if (!conflict || conflict.keep) return;
    conflict.keep = keepCid;
    conflict.rewardPending = conflict.cids.filter(function (cid) { return cid !== keepCid; });
    commit();
  }

  function resolveMonopolyReward(pid, cidGiven, optKey) {
    var conflict = (S.pendingMonopoly || []).filter(function (c) { return c.playerId === pid; })[0];
    if (!conflict || !conflict.keep) return;
    var p = playerById(pid);
    conflict.rewards[cidGiven] = applyMonopolyReward(p, cidGiven, optKey);
    sellExcessForMonopoly(p, cidGiven);
    conflict.rewardPending = (conflict.rewardPending || []).filter(function (c) { return c !== cidGiven; });
    if (!conflict.rewardPending.length) conflict.resolved = true;
    maybeProceedFromMonopoly();
  }

  function maybeProceedFromMonopoly() {
    var pending = S.pendingMonopoly || [];
    var stillPending = pending.filter(function (c) { return !c.resolved; });
    if (stillPending.length) { commit(); return; }
    S.pendingMonopoly = [];
    proceedToEvents();
  }

  function proceedToEvents() {
    var deck = (D.EVENTOS[S.round] || []).filter(function (e) { return S.revealedEventIds.indexOf(e.id) === -1; });
    shuffle(deck);
    var picked = deck.slice(0, 2);
    picked.forEach(function (e) { S.revealedEventIds.push(e.id); });
    S._justRevealed = picked;
    S.phase = 9;
    commit();
  }

  function renderMonopolyResolution() {
    var myId = getIdentity();
    var pending = (S.pendingMonopoly || []).filter(function (c) { return !c.resolved; });
    // Bots deciden solos: se quedan con su propia empresa si está en conflicto, si no con la de más acciones,
    // y toman la primera recompensa disponible.
    var pendingBot = pending.filter(function (c) { return playerById(c.playerId).isBot; })[0];
    if (pendingBot) {
      var bp = playerById(pendingBot.playerId);
      if (!pendingBot.keep) {
        var keep = pendingBot.cids.indexOf(bp.companyId) !== -1 ? bp.companyId :
          pendingBot.cids.slice().sort(function (a, b) { return (bp.acciones[b] || 0) - (bp.acciones[a] || 0); })[0];
        scheduleBot(function () { resolveMonopolyChoice(pendingBot.playerId, keep); });
        waitScreen("Regla antimonopolio", esc(bp.name) + " (CPU) está decidiendo con cuál empresa quedarse.");
      } else {
        var cidGiven = pendingBot.rewardPending[0];
        var opts = monopolyRewardOptions(bp, cidGiven);
        var optKey = opts.length ? opts[0].key : null;
        scheduleBot(function () { resolveMonopolyReward(pendingBot.playerId, cidGiven, optKey); });
        waitScreen("Regla antimonopolio", esc(bp.name) + " (CPU) está eligiendo su recompensa.");
      }
      return;
    }
    var mine = pending.filter(function (c) { return c.playerId === myId; })[0];
    if (!mine) {
      var names = pending.map(function (c) { return playerById(c.playerId).name; });
      waitScreen("Regla antimonopolio", "Esperando a que decida(n): " + names.join(", "));
      return;
    }
    var p = playerById(myId);
    if (!mine.keep) {
      root.innerHTML = header("Mercado accionario") + '<div class="screen"><h2>¡Controlas dos o más empresas!</h2>' +
        '<p class="muted">Tienes más acciones que cualquier otro jugador en más de una empresa. Debes quedarte con una sola; ' +
        'de las que sueltas, te llevas una oficina o una tecnología como recompensa, y el resto de tus acciones ahí se venden al mercado.</p>' +
        mine.cids.map(function (cid) {
          return '<div class="frow"><div><b>' + D.COMPANIES[cid].name + '</b><span class="muted"> · tienes ' + (p.acciones[cid] || 0) + ' acción(es) · valor $' + companyStockValue(cid) + '</span></div>' +
            '<button class="btn small keepCompany" data-c="' + cid + '">Quedarme con esta</button></div>';
        }).join("") + '</div>';
      wireWhoBtn();
      root.querySelectorAll(".keepCompany").forEach(function (btn) {
        btn.onclick = function () { resolveMonopolyChoice(myId, btn.dataset.c); };
      });
      return;
    }
    // Ya eligió con cuál quedarse — ahora elige su recompensa por cada empresa que suelta.
    var cidGiven = mine.rewardPending[0];
    var opts = monopolyRewardOptions(p, cidGiven);
    root.innerHTML = header("Mercado accionario") + '<div class="screen"><h2>Elige tu recompensa</h2>' +
      '<p class="muted">Al soltar ' + D.COMPANIES[cidGiven].name + ', te llevas una oficina o una tecnología de esa empresa.</p>' +
      (opts.length ? opts.map(function (o) {
        return '<div class="frow"><div><b>' + esc(o.label) + '</b></div><button class="btn small pickReward" data-k="' + o.key + '">Elegir</button></div>';
      }).join("") : '<p class="muted">No hay recompensas disponibles — ya tienes todo.</p><button class="btn primary big" id="noReward">Continuar sin recompensa</button>') +
      '</div>';
    wireWhoBtn();
    root.querySelectorAll(".pickReward").forEach(function (btn) {
      btn.onclick = function () { resolveMonopolyReward(myId, cidGiven, btn.dataset.k); };
    });
    var nb = $("#noReward");
    if (nb) nb.onclick = function () { resolveMonopolyReward(myId, cidGiven, null); };
  }

  function resolveStockAndEvents() {
    resolveStockMarket();
    var pending = detectMonopolyConflicts();
    if (pending.length) { S.pendingMonopoly = pending; commit(); return; }
    proceedToEvents();
  }

  function shuffle(arr) {
    for (var i = arr.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = arr[i]; arr[i] = arr[j]; arr[j] = t; }
    return arr;
  }

  // ---------------- FASE 9: EVENTOS + BOLSA ENTRE JUGADORES ----------------
  // Rediseño: en vez de "registrar" un trato ya cerrado, ahora se manda una propuesta
  // (a un jugador específico o abierta a cualquiera) y esa persona la acepta o rechaza.
  // También se agrega "vender al mercado" al valor actual de la acción, con la comisión
  // del libro de reglas ($1 si vale <$20 · $2 entre $20 y $30 · $3 si vale más de $30).
  // Cada propuesta dice explícitamente qué da y qué pide quien la manda, así que no hay
  // ambigüedad sobre si "compra" o "vende": "Jorge ofrece 2 acciones de Lusso A CAMBIO DE $40".
  // Lo que se ofrece/pide puede ser acciones de una empresa, dinero, o un nivel de tecnología.
  function tradeItemOptions(p) {
    var opts = [{ key: "dinero", label: "Dinero", type: "dinero" }];
    Object.keys(D.COMPANIES).forEach(function (cid) {
      if (S.companiesInUse.indexOf(cid) === -1) return;
      opts.push({ key: "acciones:" + cid, label: "Acciones de " + D.COMPANIES[cid].name, type: "acciones", cid: cid });
    });
    Object.keys(D.PATENTES).forEach(function (b) {
      opts.push({ key: "tech:" + b, label: "Tecnología: " + D.PATENTES[b].nombre, type: "tech", branch: b });
    });
    return opts;
  }
  function tradeItemLabel(item) {
    if (!item) return "nada";
    if (item.type === "dinero") return fmt(item.amount || 0);
    if (item.type === "acciones") return (item.qty || 0) + " acción(es) de " + D.COMPANIES[item.cid].name;
    if (item.type === "tech") return "1 nivel de " + D.PATENTES[item.branch].nombre;
    return "?";
  }
  // ¿Puede este jugador entregar este item ahora mismo? (para validar al aceptar/enviar)
  function canGive(p, item) {
    if (!item) return true;
    if (item.type === "dinero") return p.cash >= (item.amount || 0);
    if (item.type === "acciones") return (p.acciones[item.cid] || 0) >= (item.qty || 0);
    if (item.type === "tech") return (p.patentes[item.branch] || 0) >= 1;
    return false;
  }
  function applyGive(p, item) {
    if (!item) return;
    if (item.type === "dinero") p.cash -= (item.amount || 0);
    else if (item.type === "acciones") p.acciones[item.cid] = (p.acciones[item.cid] || 0) - item.qty;
    else if (item.type === "tech") p.patentes[item.branch] = Math.max(0, (p.patentes[item.branch] || 0) - 1);
  }
  function applyReceive(p, item) {
    if (!item) return;
    if (item.type === "dinero") p.cash += (item.amount || 0);
    else if (item.type === "acciones") p.acciones[item.cid] = (p.acciones[item.cid] || 0) + item.qty;
    else if (item.type === "tech") p.patentes[item.branch] = Math.min(5, (p.patentes[item.branch] || 0) + 1);
  }
  function readTradeItemFromInputs(prefix) {
    var key = $("#" + prefix + "Type") ? $("#" + prefix + "Type").value : "";
    if (!key) return null;
    if (key === "dinero") {
      var amount = parseInt($("#" + prefix + "Amount").value, 10) || 0;
      return amount > 0 ? { type: "dinero", amount: amount } : null;
    }
    if (key.indexOf("acciones:") === 0) {
      var cid = key.slice("acciones:".length);
      var qty = parseInt($("#" + prefix + "Qty").value, 10) || 0;
      return qty > 0 ? { type: "acciones", cid: cid, qty: qty } : null;
    }
    if (key.indexOf("tech:") === 0) {
      return { type: "tech", branch: key.slice("tech:".length) };
    }
    return null;
  }
  function tradeItemFieldsHtml(prefix, opts) {
    return '<select id="' + prefix + 'Type">' + '<option value="">(elige qué)</option>' +
      opts.map(function (o) { return '<option value="' + o.key + '">' + esc(o.label) + '</option>'; }).join("") + '</select>' +
      '<input type="number" min="1" id="' + prefix + 'Amount" placeholder="monto $" style="display:none;">' +
      '<input type="number" min="1" id="' + prefix + 'Qty" placeholder="# acciones" style="display:none;">';
  }
  function wireTradeItemFields(prefix) {
    var sel = $("#" + prefix + "Type"), amountEl = $("#" + prefix + "Amount"), qtyEl = $("#" + prefix + "Qty");
    if (!sel) return;
    sel.onchange = function () {
      var key = sel.value;
      amountEl.style.display = key === "dinero" ? "" : "none";
      qtyEl.style.display = key.indexOf("acciones:") === 0 ? "" : "none";
    };
  }

  function tradeSectionHtml(myId) {
    if (myId === "spectator" || myId === null) return '';
    var me = playerById(myId);
    if (!me) return '';
    var others = S.players.filter(function (p) { return p.id !== myId; });
    var myShareOptions = Object.keys(me.acciones || {}).filter(function (cid) { return (me.acciones[cid] || 0) > 0; });
    S.tradeOffers = S.tradeOffers || [];
    var received = S.tradeOffers.filter(function (o) { return o.status === "pendiente" && (o.toId === myId || o.toId === null) && o.fromId !== myId; });
    var sent = S.tradeOffers.filter(function (o) { return o.status === "pendiente" && o.fromId === myId; });
    var opts = tradeItemOptions(me);

    var html = '<div class="card"><h3>Vender acciones al mercado</h3>' +
      '<p class="muted">Vendes al valor oficial actual de la acción; se cobra la comisión del libro de reglas.</p>' +
      (myShareOptions.length ? myShareOptions.map(function (cid) {
        var sv = companyStockValue(cid), com = stockSellCommission(sv);
        return '<div class="frow"><div><b>' + D.COMPANIES[cid].name + '</b><span class="muted"> tienes ' + me.acciones[cid] + ' · valor $' + sv + ' · comisión $' + com + '</span></div>' +
          '<input type="number" min="1" max="' + me.acciones[cid] + '" class="sellQty" data-c="' + cid + '" placeholder="# acc." style="width:64px">' +
          '<button class="btn small sellMarket" data-c="' + cid + '">Vender</button></div>';
      }).join("") : '<p class="muted">No tienes acciones para vender.</p>') +
      '</div>';

    html += '<div class="card"><h3>Proponer un trato</h3>' +
      '<p class="muted">Dices exactamente qué ofreces y qué pides a cambio — puede ser acciones, dinero o tecnología, en cualquier combinación. ' +
      'El valor oficial de la acción no cambia por esto.</p>' +
      '<div class="prow"><select id="tradeTo"><option value="">(cualquiera puede aceptar)</option>' + others.map(function (p) { return '<option value="' + p.id + '">' + esc(p.name) + '</option>'; }).join("") + '</select></div>' +
      '<p class="muted" style="margin-bottom:2px;"><b>Ofreces:</b></p><div class="prow">' + tradeItemFieldsHtml("give", opts) + '</div>' +
      '<p class="muted" style="margin-bottom:2px;"><b>A cambio de:</b></p><div class="prow">' + tradeItemFieldsHtml("want", opts) + '</div>' +
      '<button class="btn small" id="doTrade">Enviar propuesta</button>' +
      '</div>';

    if (sent.length) {
      html += '<div class="card"><h3>Tus propuestas enviadas</h3>' + sent.map(function (o) {
        return '<div class="salerow">Ofreces ' + tradeItemLabel(o.give) + ' a cambio de ' + tradeItemLabel(o.want) +
          (o.toId ? (' — a ' + esc(playerLabel(o.toId))) : ' (abierta a cualquiera)') +
          ' <button class="btn small cancelOffer" data-id="' + o.id + '">Cancelar</button></div>';
      }).join("") + '</div>';
    }
    if (received.length) {
      html += '<div class="card"><h3>Propuestas para ti</h3>' + received.map(function (o) {
        var from = playerById(o.fromId);
        return '<div class="salerow"><b>' + esc(from ? from.name : "?") + '</b> ofrece ' + tradeItemLabel(o.give) + ' a cambio de ' + tradeItemLabel(o.want) +
          ' <button class="btn small acceptOffer" data-id="' + o.id + '">Aceptar</button>' +
          ' <button class="btn small rejectOffer" data-id="' + o.id + '">Rechazar</button></div>';
      }).join("") + '</div>';
    }
    if ((S.trades || []).length) {
      html += '<div class="muted" style="margin-top:10px;">' + S.trades.slice(0, 6).map(function (t) { return esc(t); }).join('<br>') + '</div>';
    }
    return html;
  }
  function wireTradeSection(myId) {
    var me = playerById(myId);
    wireTradeItemFields("give");
    wireTradeItemFields("want");
    root.querySelectorAll(".sellMarket").forEach(function (btn) {
      btn.onclick = function () {
        var cid = btn.dataset.c;
        var qtyInp = root.querySelector('.sellQty[data-c="' + cid + '"]');
        var qty = parseInt(qtyInp ? qtyInp.value : "0", 10) || 0;
        if (qty <= 0) { showError("Indica cuántas acciones quieres vender."); return; }
        if ((me.acciones[cid] || 0) < qty) { showError("No tienes esa cantidad de acciones."); return; }
        var sv = companyStockValue(cid), com = stockSellCommission(sv);
        var ingreso = Math.max(0, qty * sv - com);
        me.acciones[cid] = (me.acciones[cid] || 0) - qty;
        me.cash += ingreso;
        var msg = me.name + " vendió " + qty + " acción(es) de " + D.COMPANIES[cid].name + " al mercado por " + fmt(ingreso) + " (comisión $" + com + ")";
        log(msg);
        S.trades = S.trades || []; S.trades.unshift(msg);
        commit();
      };
    });
    var btn = $("#doTrade");
    if (btn) btn.onclick = function () {
      var toEl = $("#tradeTo");
      var give = readTradeItemFromInputs("give");
      var want = readTradeItemFromInputs("want");
      if (!give && !want) { showError("Indica al menos qué ofreces o qué pides."); return; }
      if (give && !canGive(me, give)) { showError("No tienes eso que estás ofreciendo."); return; }
      S.tradeOffers = S.tradeOffers || [];
      S.tradeSeq = (S.tradeSeq || 0) + 1;
      S.tradeOffers.push({ id: "t" + S.tradeSeq, fromId: myId, toId: (toEl && toEl.value) || null, give: give, want: want, status: "pendiente" });
      log(me.name + " ofrece " + tradeItemLabel(give) + " a cambio de " + tradeItemLabel(want) + ((toEl && toEl.value) ? (" a " + playerLabel(toEl.value)) : " (abierta a cualquiera)"));
      commit();
    };
    root.querySelectorAll(".cancelOffer").forEach(function (b) {
      b.onclick = function () {
        var o = (S.tradeOffers || []).filter(function (x) { return x.id === b.dataset.id; })[0];
        if (o) o.status = "cancelada";
        commit();
      };
    });
    root.querySelectorAll(".rejectOffer").forEach(function (b) {
      b.onclick = function () {
        var o = (S.tradeOffers || []).filter(function (x) { return x.id === b.dataset.id; })[0];
        if (o) o.status = "rechazada";
        commit();
      };
    });
    root.querySelectorAll(".acceptOffer").forEach(function (b) {
      b.onclick = function () {
        var o = (S.tradeOffers || []).filter(function (x) { return x.id === b.dataset.id; })[0];
        if (!o || o.status !== "pendiente") return;
        var from = playerById(o.fromId);
        if (!from || (o.give && !canGive(from, o.give))) { showError("Esa oferta ya no es válida (quien la mandó ya no tiene lo ofrecido)."); if (o) o.status = "cancelada"; commit(); return; }
        if (o.want && !canGive(me, o.want)) { showError("No tienes lo que esta oferta pide a cambio."); return; }
        applyGive(from, o.give); applyReceive(me, o.give);
        applyGive(me, o.want); applyReceive(from, o.want);
        o.status = "aceptada";
        var msg = from.name + " y " + me.name + " cerraron un trato: " + tradeItemLabel(o.give) + " a cambio de " + tradeItemLabel(o.want) + " (trato directo — el valor de la acción no cambia)";
        log(msg);
        S.trades = S.trades || []; S.trades.unshift(msg);
        commit();
      };
    });
  }

  // Valor estimado de un item de trato (para que la CPU decida si un trato le conviene).
  function itemValue(item) {
    if (!item) return 0;
    if (item.type === "dinero") return item.amount || 0;
    if (item.type === "acciones") return (item.qty || 0) * companyStockValue(item.cid);
    if (item.type === "tech") {
      var b = D.PATENTES[item.branch], lvl1 = b && b.niveles && b.niveles[1];
      return lvl1 ? lvl1.compra : 5;
    }
    return 0;
  }
  // La CPU revisa las propuestas de trato pendientes dirigidas a ella (o abiertas a cualquiera)
  // y acepta las que claramente le convienen: compara el valor de lo que recibe contra lo que
  // entrega, con un pequeño margen para no aceptar tratos casi neutros que no le aportan nada.
  function botConsiderTrades(p) {
    S.tradeOffers = S.tradeOffers || [];
    var offers = S.tradeOffers.filter(function (o) { return o.status === "pendiente" && o.fromId !== p.id && (o.toId === p.id || o.toId === null); });
    offers.forEach(function (o) {
      if (o.status !== "pendiente") return;
      var from = playerById(o.fromId);
      if (!from || (o.give && !canGive(from, o.give))) { o.status = "cancelada"; return; }
      if (o.want && !canGive(p, o.want)) return;
      var valorRecibido = itemValue(o.give), valorEntregado = itemValue(o.want);
      if (valorRecibido > 0 && valorRecibido >= valorEntregado * 1.05) {
        applyGive(from, o.give); applyReceive(p, o.give);
        applyGive(p, o.want); applyReceive(from, o.want);
        o.status = "aceptada";
        var msg = from.name + " y " + p.name + " (CPU) cerraron un trato: " + tradeItemLabel(o.give) + " a cambio de " + tradeItemLabel(o.want);
        log(msg);
        S.trades = S.trades || []; S.trades.unshift(msg);
      }
    });
  }

  function renderEvents() {
    var myId = getIdentity();
    var pendingBot = S.players.filter(function (p) { return p.isBot && !S.ackEvents[p.id]; })[0];
    if (pendingBot) { scheduleBot(function () { botConsiderTrades(pendingBot); S.ackEvents[pendingBot.id] = true; maybeAdvanceFromEvents(); }); }
    var iAcked = myId && myId !== "spectator" && S.ackEvents[myId];
    var missing = S.players.filter(function (p) { return !S.ackEvents[p.id]; }).map(function (p) { return p.name; });
    root.innerHTML = header("Eventos") + '<div class="screen"><h2>Cartas de evento reveladas</h2>' +
      (S._justRevealed || []).map(function (e) {
        return '<div class="card"><h3>' + esc(e.nombre) + '</h3><p>' + esc(e.efecto) + '</p><p class="muted">Duración: ' + e.duracion + '</p></div>';
      }).join("") +
      tradeSectionHtml(myId) +
      (myId === "spectator" || myId === null ? '<p class="muted">Esperando a los jugadores…</p>' :
        iAcked ? '<p class="muted">Listo. Esperando a: ' + missing.join(", ") + '</p>' :
        '<button class="btn primary big" id="applyEvents">Listo, empezar ronda ' + (S.round + 1) + '</button>') +
      '</div>';
    wireWhoBtn();
    wireTradeSection(myId);
    var btn = $("#applyEvents");
    if (btn) btn.onclick = function () { S.ackEvents[myId] = true; maybeAdvanceFromEvents(); };
  }
  function maybeAdvanceFromEvents() {
    if (!S.players.every(function (p) { return S.ackEvents[p.id]; })) { commit(); return; }
    (S._justRevealed || []).forEach(function (e) {
      if (e.duracion === "permanente" || e.duracion === "mixta" || e.duracion === "unica_r5") S.events.active.push(e);
      else if (e.duracion === "1 ronda") S.events.active.push(e);
    });
    S._justRevealed = [];
    S.round++; S.phase = 1;
    S.players.forEach(function (p) { p.koganeUsedThisRound = false; p._devCount = 0; });
    S.ackSale = {}; S.ackAdjust = {}; S.ackEvents = {}; S.dividendVotes = {};
    computeTurnOrder();
    commit();
  }

  // ---------------- FIN DE PARTIDA ----------------
  function finishGame() {
    var stockValues = {};
    S.players.forEach(function (p) { stockValues[p.companyId] = p.stockValue; });
    S.players.forEach(function (p) { p._finalWealth = L.finalWealth(p, stockValues); });
    S.finished = true;
    commit();
  }

  function renderFinal() {
    var ranked = S.players.slice().sort(function (a, b) {
      if (b._finalWealth !== a._finalWealth) return b._finalWealth - a._finalWealth;
      return b.marketsDominatedThisRound.length - a.marketsDominatedThisRound.length;
    });
    root.innerHTML = '<div class="screen final"><h1>Fin de la partida</h1>' +
      ranked.map(function (p, i) {
        return '<div class="card ' + (i === 0 ? "winner" : "") + '"><h2>' + (i + 1) + '. ' + esc(p.name) + ' — ' + D.COMPANIES[p.companyId].name + '</h2><p>Patrimonio final: ' + fmt(p._finalWealth) + '</p></div>';
      }).join("") + '<button class="btn primary big" id="newGameBtn">Nueva partida</button></div>';
    $("#newGameBtn").onclick = function () { S = null; setIdentity(null); commit(); };
  }

  // ================================================================
  // ARRANQUE
  // ================================================================
  function migrateState(state) {
    if (!state) return state;
    state.ackSale = state.ackSale || {};
    state.ackAdjust = state.ackAdjust || {};
    state.ackEvents = state.ackEvents || {};
    state.dividendVotes = state.dividendVotes || {};
    state.trades = state.trades || [];
    state.tradeOffers = state.tradeOffers || [];
    state.tradeSeq = state.tradeSeq || 0;
    state.pendingMonopoly = state.pendingMonopoly || [];
    return state;
  }

  function boot() {
    root = $("#app");
    if (typeof firebase === "undefined" || !window.FIREBASE_CONFIG) {
      FB_STATE = "unavailable";
      render();
      return;
    }
    if (!firebase.apps.length) firebase.initializeApp(window.FIREBASE_CONFIG);
    var code = roomFromUrl() || getSavedRoom();
    if (code) {
      saveRoom(code);
      connectToRoom(code);
    }
    render();
  }

  window.addEventListener("DOMContentLoaded", boot);
  window.__MM_DEBUG = { getState: function () { return S; }, getIdentity: getIdentity, setIdentity: setIdentity };
})();
